async function financeForm(){const u=await api('/api/business-units'),def=selectedUnitId||me.business_unit_id||u[0]?.id||'';modal(`<div class="section-title"><div><h2>Manual Finance Entry</h2><div class="muted">Manual entries are source-tagged and submitted for Finance verification.</div></div><button class="btn" onclick="closeModal()">✕</button></div><form onsubmit="saveFinance(event)" enctype="multipart/form-data"><div class="grid g2"><div class="field"><label>Business Unit *</label><select name="business_unit_id" required>${u.map(x=>`<option value="${x.id}" ${String(x.id)===String(def)?'selected':''} data-no-i18n>${esc(x.name)}</option>`).join('')}</select></div><div class="field"><label>Type *</label><select name="type"><option>Expense</option><option>Revenue</option></select></div></div><div class="grid g2"><div class="field"><label>Category *</label><select name="category"><option>General Expense</option><option>Salary / Wages</option><option>Rent</option><option>Utilities</option><option>Transport</option><option>Bank Charges</option><option>Other Expense</option><option>Other Income</option></select></div><div class="field"><label>Transaction Date *</label><input name="transaction_date" type="date" required></div></div><div class="grid g3"><div class="field"><label>Original Amount *</label><input name="original_amount" type="number" step="0.01" min="0.01" required></div><div class="field"><label>Currency *</label><select name="original_currency"><option>KRW</option><option>USD</option><option>PKR</option><option>EUR</option><option>JPY</option><option>CNY</option></select></div><div class="field"><label>FX Rate to KRW *</label><input name="fx_rate" type="number" step="0.000001" min="0.000001" value="1" required></div></div><div class="grid g2"><div class="field"><label>Payment Method</label><select name="payment_method"><option>Bank</option><option>Cash</option><option>Card</option><option>Other</option></select></div><div class="field"><label>Due date</label><input name="due_date" type="date"></div></div><div class="grid g2"><div class="field"><label>Reference</label><input name="reference"></div><div class="field"><label>Receipt / Evidence</label><input name="attachments" type="file" multiple></div></div><div class="field"><label>Description *</label><textarea name="description" required></textarea></div><input type="hidden" name="source_type" value="Manual"><div class="actions"><button type="button" class="btn" onclick="closeModal()">Cancel</button><button class="btn primary">Review & Submit</button></div></form>`,'wide')}
async function saveFinance(e){e.preventDefault();const fd=new FormData(e.target),o=Object.fromEntries(fd),currency=o.original_currency||'KRW',krw=currency==='KRW'?Number(o.original_amount||0):Number(o.original_amount||0)*Number(o.fx_rate||0),ok=await confirmAction({title:'Confirm Finance Entry',message:'Review the information below. The Finance record will only be created after you confirm.',confirmLabel:'Save & Submit for Verification',details:[{label:'Business Unit',value:e.target.business_unit_id.selectedOptions[0]?.textContent||''},{label:'Type',value:systemText(o.type)},{label:'Category',value:systemText(o.category)},{label:'Amount',value:`${money(o.original_amount)} ${currency} · ₩ ${money(krw)}`},{label:'Date',value:o.transaction_date},{label:'Reference',value:o.reference||'—'}]});if(!ok)return;const btn=e.target.querySelector('[type="submit"]'),old=btn?.textContent;if(btn){btn.disabled=true;btn.textContent=tr('common.saving')}try{const r=await api('/api/finance',{method:'POST',body:fd});if(r.approval_required){if(btn){btn.disabled=false;btn.textContent=old}return toast(r.message||'Finance entry submitted for approval')}closeModal(true);toast('Finance entry saved · Pending Verification');loadView()}catch(x){if(btn){btn.disabled=false;btn.textContent=old}toast(x.message)}}
function workManager(){return !!me&&['CEO / Owner','Operations Manager','Business Unit Manager'].includes(me.role)}
