function approvalRowActions(x){return `<button class="btn small" onclick="approvalDetail(${x.id})">${esc(t('View Full History'))}</button>${x.can_review?` <button class="btn small primary" onclick="approvalDecision(${x.id},'Approved')">${esc(t('Approve'))}</button> <button class="btn small" onclick="approvalDecision(${x.id},'Changes Required')">${esc(t('Request Changes'))}</button>`:''}${x.can_resubmit?` <button class="btn small primary" onclick="approvalResubmitForm(${x.id})">${esc(t('Correct & Resubmit'))}</button>`:''}${x.can_retry_execution?` <button class="btn small primary" onclick="approvalRetryExecution(${x.id})">${esc(t('Retry Automatic Execution'))}</button>`:''}${x.can_cancel?` <button class="btn small danger" onclick="approvalDecision(${x.id},'Cancelled')">${esc(t('Cancel Request'))}</button>`:''}`}
