async function saveExcavatorSupplierMachine(e,supplierId,machineId){
  e.preventDefault();
  try{
    const payload={method:machineId?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(e.target)))};
    await api('/api/excavator/suppliers/'+supplierId+'/machines'+(machineId?'/'+machineId:''),payload);
    toast(machineId?'Machine updated':'Machine added to supplier availability list');
    excavatorSupplierMachines(supplierId);
  }catch(x){toast(x.message)}
}

