function filterBuyerRows(){const q=(document.getElementById('buyerSearch')?.value||'').toLowerCase();document.querySelectorAll('#buyerTable tr[data-search]').forEach(r=>r.style.display=r.dataset.search.includes(q)?'':'none')}
function countryFlag(country){const m={'Pakistan':'🇵🇰','South Korea':'🇰🇷','Korea':'🇰🇷','United Arab Emirates':'🇦🇪','UAE':'🇦🇪','Saudi Arabia':'🇸🇦','China':'🇨🇳','Japan':'🇯🇵','United States':'🇺🇸','USA':'🇺🇸','United Kingdom':'🇬🇧','UK':'🇬🇧','Turkey':'🇹🇷','Germany':'🇩🇪','France':'🇫🇷'};return m[String(country||'').trim()]||'🌐'}
