function buyerCountryOptions(selected=''){return `<option value="">Select country</option>`+buyerCountries.map(c=>`<option value="${esc(c)}" ${String(selected||'')===c?'selected':''}>${esc(c)}</option>`).join('')}
function buyerTypeChanged(){
  const type=document.querySelector('form [name="buyer_type"]'),country=document.querySelector('form [name="country"]');
  if(!type||!country)return;
  if(type.value==='Local'){country.value='South Korea';country.disabled=true;country.required=true}
  else{const wasLocal=country.value==='South Korea'&&country.dataset.autoset==='1';country.disabled=false;if(wasLocal)country.value='';country.required=true}
  country.dataset.autoset=type.value==='Local'?'1':'0';
}
