async function saveExcavatorBuyer(e,id){e.preventDefault();try{const country=e.target.querySelector('[name="country"]');if(country?.disabled)country.disabled=false;const o=Object.fromEntries(new FormData(e.target));if(o.buyer_type==='Local')o.country='South Korea';if(!o.country)throw new Error('Please select the buyer country.');await api('/api/excavator/buyers'+(id?'/'+id:''),{method:id?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(o)});closeModal();toast(id?'Buyer updated':'Buyer added');excavatorBuyers(document.getElementById('content'))}catch(x){toast(x.message)}}
