async function excavator(c){
  const [d,assets]=await Promise.all([api('/api/excavator/overview'),api('/api/excavator/assets')]); const a=assets;
  c.innerHTML=title('Excavator Operations','Used-machine purchase → costs → sale → payment lifecycle',`<button class="btn" onclick="excavatorSuppliers()">Suppliers</button><button class="btn" onclick="go('excavatorBuyers')">Buyers</button>`)+`<div class="grid g4"><div class="card stat"><div class="label">Open Machines</div><div class="value">${d.summary.open}</div></div><div class="card stat"><div class="label">In Yard</div><div class="value">${d.summary.inYard}</div></div><div class="card stat"><div class="label">Ready for Sale</div><div class="value">${d.summary.ready}</div></div><div class="card stat"><div class="label">Profit / Margin</div><div class="value">₩ ${money(d.summary.margin)}</div></div></div>`+
  `<div class="card" style="margin-top:16px"><div class="section-title"><div><h2 style="margin:0">Machines / Deals</h2><div class="muted">Search by deal no., machine name, make, model, serial/chassis or supplier</div></div><button class="btn primary" onclick="excavatorNewMachine()">+ Buy Machine</button></div><div class="grid g3" style="margin:12px 0"><div class="field"><label>Search Machines / Deals</label><input id="excavatorMachineSearch" type="search" placeholder="Search deal no., machine name, make, model, serial or supplier..." oninput="applyExcavatorMachineFilters()"></div><div class="field"><label>Filter</label><select id="excavatorMachineFilter" onchange="applyExcavatorMachineFilters()"><option value="All">All Machines</option><option value="Open">Open</option><option value="Sold / Completed">Sold / Completed</option><option value="Profit">Profit</option><option value="Loss">Loss</option><option value="Not Sold">Not Sold</option></select></div><div class="field"><label>Sort</label><select id="excavatorMachineSort" onchange="sortExcavatorMachines()"><option value="newest">Newest</option><option value="oldest">Oldest</option><option value="name">Machine Name</option><option value="purchase_high">Purchase Price: High → Low</option><option value="purchase_low">Purchase Price: Low → High</option><option value="cost_high">Total Cost: High → Low</option><option value="profit_high">Profit: High → Low</option><option value="profit_low">Profit: Low → High</option></select></div></div><div class="machine-list" id="excavatorMachineList">${a.map(x=>{
    const total=Number(x.total_cost||d.assets.find(z=>z.id===x.id)?.total_cost||0), sale=Number(x.sale_amount||0), pnl=Number(x.profit_loss??(sale-total)), pnlStatus=x.profit_loss_status||(sale<=0?'Not Sold':(pnl>=0?'Profit':'Loss'));
    const search=[x.asset_no,x.machine_name,x.machine_display_name,x.make,x.model,x.serial_no,x.type,x.lifecycle_stage,x.supplier_name,x.supplier_location].filter(Boolean).join(' ').toLowerCase(); const closed=x.lifecycle_stage==='Sold / Completed'; const pnlPill=pnlStatus==='Profit'?'good':pnlStatus==='Loss'?'bad':'blue';
    return `<div class="machine-card" data-ex-search="${esc(search)}" data-stage="${esc(x.lifecycle_stage||'Purchased')}" data-pnl="${esc(pnlStatus)}" data-created="${Number(x.id||0)}" data-name="${esc((x.machine_name||x.machine_display_name||'').toLowerCase())}" data-purchase="${Number(x.purchase_price||0)}" data-cost="${Number(total||0)}" data-profit="${Number(pnl||0)}"><div><div class="machine-title"><b>${esc(x.asset_no)}</b><span class="pill ${closed?'good':x.lifecycle_stage==='Sold / Payment Pending'?'warn':x.lifecycle_stage==='Under Repair'?'warn':'blue'}">${esc(x.lifecycle_stage||'Purchased')}</span></div><h3>${esc(x.machine_name||x.machine_display_name||((x.make||'')+' '+(x.model||'')))}</h3><div class="muted">${esc(x.type||'Excavator')} · ${esc(x.make||'')} · ${esc(x.model||'')} · ${esc(x.serial_no||'No serial')} · ${esc(x.condition_status||'Used')}</div>${x.supplier_name?`<div class="muted" style="margin-top:6px"><b>Seller / Supplier:</b> ${esc(x.supplier_name)}${x.supplier_location?` · ${esc(x.supplier_location)}`:''}</div>`:''}</div><div class="machine-numbers"><div><small>Purchase</small><b>₩ ${money(x.purchase_price)}</b></div><div><small>Total Cost</small><b>₩ ${money(total)}</b></div><div><small>Sale</small><b>₩ ${money(sale)}</b></div></div><div class="machine-meta">${closed?`<span class="pill ${pnlPill}">${pnlStatus}: ₩ ${money(Math.abs(pnl))}</span>`:'<span class="pill blue">Not Sold</span>'}</div><div class="actions"><button class="btn primary" onclick="excavatorOpenMachine(${x.id})">Open Machine</button>${!closed||me.role==='CEO / Owner'?`<button class="btn" onclick="excavatorAddCost(${x.id})">+ Cost</button>`:''}<button class="btn" onclick="excavatorSell(${x.id})">${closed?'Update Sale':'Sell'}</button><button class="btn" onclick="excavatorPayments(${x.id})">Payments</button><button class="btn" onclick="excavatorDocuments(${x.id})">Documents</button>${me.role==='CEO / Owner'?`<button class="btn danger" onclick="deleteExcavatorAsset(${x.id})">Delete</button>`:''}</div></div>`}).join('')||'<div class="empty">No machines yet. Start with <b>+ Buy Machine</b>.</div>'}</div></div>`;
}

function filterExcavatorMachines(value){ applyExcavatorMachineFilters(); }
function applyExcavatorMachineFilters(){
  const q=String(document.getElementById('excavatorMachineSearch')?.value||'').trim().toLowerCase();
  const f=String(document.getElementById('excavatorMachineFilter')?.value||'All');
  document.querySelectorAll('#excavatorMachineList .machine-card').forEach(el=>{
    const search=el.dataset.exSearch||'', stage=el.dataset.stage||'', pnl=el.dataset.pnl||'';
    const qok=!q||search.includes(q);
    const fok=f==='All'||stage===f||(f==='Open'&&!['Sold / Completed','Cancelled'].includes(stage))||(f==='Profit'&&pnl==='Profit')||(f==='Loss'&&pnl==='Loss')||(f==='Not Sold'&&pnl==='Not Sold');
    el.style.display=qok&&fok?'':'none';
  });
}
function sortExcavatorMachines(){
  const list=document.getElementById('excavatorMachineList'); if(!list)return;
  const mode=document.getElementById('excavatorMachineSort')?.value||'newest';
  const cards=[...list.querySelectorAll('.machine-card')];
  const num=k=>Number(k||0);
  cards.sort((a,b)=>{
    if(mode==='oldest') return num(a.dataset.created)-num(b.dataset.created);
    if(mode==='name') return (a.dataset.name||'').localeCompare(b.dataset.name||'');
    if(mode==='purchase_high') return num(b.dataset.purchase)-num(a.dataset.purchase);
    if(mode==='purchase_low') return num(a.dataset.purchase)-num(b.dataset.purchase);
    if(mode==='cost_high') return num(b.dataset.cost)-num(a.dataset.cost);
    if(mode==='profit_high') return num(b.dataset.profit)-num(a.dataset.profit);
    if(mode==='profit_low') return num(a.dataset.profit)-num(b.dataset.profit);
    return num(b.dataset.created)-num(a.dataset.created);
  });
  cards.forEach(x=>list.appendChild(x)); applyExcavatorMachineFilters();
}

