function togglePurchaseTokenFields(form){const amount=Number(form?.querySelector('[name="purchase_token"]')?.value||0),box=form?.querySelector('#purchaseTokenFields'),reference=form?.querySelector('[name="token_payment_reference"]'),date=form?.querySelector('[name="token_paid_date"]'),evidence=form?.querySelector('[name="payment_evidence"]');if(box)box.style.display=amount>0?'block':'none';for(const input of [reference,date,evidence])if(input)input.required=amount>0}
async function selectBuySupplier(value){
  const suppliers=window._buySuppliers||[],exact=suppliers.find(o=>String(o.name||'').toLowerCase()===String(value||'').trim().toLowerCase());
  const id=document.getElementById('buySupplierId'),opt=document.getElementById('buySupplierOption'),box=document.getElementById('newSupplierFields'),machineBox=document.getElementById('supplierMachineBox'),machineSelect=document.getElementById('buySupplierMachine'),machineId=document.getElementById('buySupplierMachineId');
  if(!id||!opt||!box||!machineBox||!machineSelect||!machineId)return;
  machineId.value='';window._buySupplierMachines=[];machineSelect.innerHTML='<option value="">New / Other Machine</option>';machineBox.style.display='none';
  if(String(value||'').trim()==='Other / New Supplier'){
    id.value='';opt.value='Other / New Supplier';box.style.display='block';return;
  }
  if(exact){
    id.value=String(exact.id);opt.value='';box.style.display='none';machineBox.style.display='block';
    try{
      const d=await api('/api/excavator/suppliers/'+exact.id+'/machines');
      window._buySupplierMachines=d.listed||[];
      machineSelect.innerHTML='<option value="">New / Other Machine</option>'+window._buySupplierMachines.map(m=>`<option value="${m.id}">${esc(m.machine_name||'Machine')} · ${esc(m.make||'')} ${esc(m.model||'')} · ${m.year||'Year n/a'} · ₩ ${money(m.asking_price||0)}</option>`).join('');
      if(!window._buySupplierMachines.length)machineSelect.innerHTML='<option value="">New / Other Machine — no available supplier-listed machines</option>';
    }catch(e){toast('Supplier machine list could not be loaded: '+e.message)}
  }else{
    id.value='';opt.value='';box.style.display='none';
  }
}
function selectSupplierListedMachine(value){
  const machine=(window._buySupplierMachines||[]).find(x=>String(x.id)===String(value)),form=document.querySelector('#buySupplierMachine')?.closest('form'),id=document.getElementById('buySupplierMachineId');
  if(!form||!id)return;
  id.value=machine?String(machine.id):'';
  if(!machine)return;
  const set=(name,val)=>{const el=form.querySelector(`[name="${name}"]`);if(el)el.value=val??''};
  set('machine_name',machine.machine_name||'');
  set('type',machine.machine_type||'Excavator');
  set('condition_status',machine.condition_status||'Used');
  set('make',machine.make||'');
  set('model',machine.model||'');
  set('year',machine.year||'');
  set('serial_no',machine.serial_no||'');
  set('purchase_price',Number(machine.asking_price||0)>0?machine.asking_price:'');
}

async function saveSimpleExcavatorMachine(e){
  e.preventDefault();
  const form=e.target,btn=form.querySelector('button[type="submit"]');
  if(btn){btn.disabled=true;btn.textContent=tr('common.saving')}
  try{
    const o=Object.fromEntries(new FormData(form));
    if(!o.asset_no||!o.machine_name||!o.make||!o.model||!o.purchase_date||Number(o.purchase_price)<=0) throw new Error('Please complete Deal No., Machine Name, Make, Model, Purchase Date and Purchase Price.');
    const result=await api('/api/excavator/assets',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(o)});
    if(result.approval_required){if(btn){btn.disabled=false;btn.textContent=t('Save Machine')}toast(result.message||'Machine purchase submitted for approval');return;}
    closeModal();
    if(result.new_supplier) toast('Machine saved · New supplier added to the supplier list for future use');
    else if(result.requirement_matches) toast(`Machine saved · ${result.requirement_matches} supplier requirement match(es) found`);
    else toast('Machine saved successfully');
    loadView().catch(err=>console.error('Excavator refresh:',err));
  }catch(x){
    if(btn){btn.disabled=false;btn.textContent=t('Save Machine')}
    console.error('Excavator save:',x);
    toast(x.message||'Machine could not be saved');
  }
}
async function excavatorOpenMachine(id){
  const [assets,tx,docs,hist,payments]=await Promise.all([api('/api/excavator/assets'),api('/api/excavator/assets/'+id+'/transactions'),api('/api/excavator/assets/'+id+'/documents'),api('/api/excavator/assets/'+id+'/history'),api('/api/excavator/assets/'+id+'/payments')]); const a=assets.find(x=>x.id==id); if(!a)return;
  const costTypes=['Purchase','Logistics','Repair','Part Purchase','Customs Duty','Tax / VAT','Shipping / Freight','Commission','Documentation / Clearance','Other Cost']; const costs=tx.filter(x=>costTypes.includes(x.type)&&x.status!=='Cancelled'); const totalCost=Number(a.total_cost||costs.reduce((n,x)=>n+Number(x.amount||0),0)); const sale=Number(a.sale_amount||0); const paid=Number(a.sale_paid||payments.filter(x=>x.payment_type==='Sale'&&x.status==='Paid').reduce((n,x)=>n+Number(x.amount||0),0)); const outstanding=Math.max(0,sale-paid); const profit=sale-totalCost; const pnlStatus=sale<=0?'Not Sold':(profit>=0?'Profit':'Loss'); const paymentStatus=a.sale_payment_status||(sale<=0?'Not Sold':outstanding<=0?'Paid':paid>0?'Partially Paid':'Pending');
  modal(`<div class="machine-header"><div><div class="muted">Machine / Deal</div><h2 style="margin:3px 0">${esc(a.asset_no)}</h2><div>${esc(a.machine_name||a.machine_display_name||((a.make||'')+' '+(a.model||'')))} · ${esc(a.type)}</div></div><span class="pill ${a.lifecycle_stage==='Sold / Completed'?'good':a.lifecycle_stage==='Sold / Payment Pending'?'warn':'blue'}">${esc(a.lifecycle_stage||'Purchased')}</span></div><div class="grid g4" style="margin:16px 0"><div class="card stat"><small>Purchase</small><b>₩ ${money(a.purchase_price)}</b></div><div class="card stat"><small>Total Cost</small><b>₩ ${money(totalCost)}</b></div><div class="card stat"><small>Sale</small><b>₩ ${money(sale)}</b></div><div class="card stat"><small>Profit / Loss</small><b class="${pnlStatus==='Profit'?'good':pnlStatus==='Loss'?'bad':''}">${pnlStatus==='Not Sold'?'—':`${pnlStatus}: ₩ ${money(Math.abs(profit))}`}</b></div></div><div class="card" style="margin-bottom:16px"><div class="section-title"><h3>Buyer Payment</h3><span class="pill ${paymentStatus==='Paid'?'good':paymentStatus==='Not Sold'?'blue':'warn'}">${esc(paymentStatus)}</span></div><div class="grid g3"><div><small>Sale Amount</small><b>₩ ${money(sale)}</b></div><div><small>Paid</small><b>₩ ${money(paid)}</b></div><div><small>Outstanding</small><b>₩ ${money(outstanding)}</b></div></div></div><div class="simple-actions">${a.lifecycle_stage!=='Sold / Completed'||me.role==='CEO / Owner'?`<button class="btn primary" onclick="excavatorAddCost(${id})">+ Add Cost</button>`:''}<button class="btn primary" onclick="excavatorSell(${id})">${a.lifecycle_stage==='Sold / Completed'?'Update Sale':'Sell Machine'}</button><button class="btn" onclick="excavatorPayments(${id})">Payments</button><button class="btn" onclick="excavatorDocuments(${id})">Documents (${docs.length})</button>${a.lifecycle_stage==='Sold / Completed'?'':`<button class="btn" onclick="excavatorChangeStage(${id})">Status / Stage</button>`}</div><div class="machine-sections"><div class="card"><div class="section-title"><h3>Purchase</h3><button class="btn small" onclick="excavatorEditMachine(${id})">Edit</button></div><div class="row"><span>Purchase date</span><b>${esc(a.purchase_date||'—')}</b></div><div class="row"><span>Price</span><b>₩ ${money(a.purchase_price)}</b></div><div class="row"><span>Seller / Supplier</span><b>${esc(a.supplier_name||((tx.find(x=>x.type==='Purchase')||{}).counterparty)||'—')}</b></div>${a.supplier_phone?`<div class="row"><span>Contact</span><b>${esc(a.supplier_phone)}</b></div>`:''}${a.supplier_location?`<div class="row"><span>Location</span><b>${esc(a.supplier_location)}</b></div>`:''}<div class="row"><span>Purchase Payment</span><b>${esc(a.purchase_status||'Pending')} · Paid ₩ ${money(a.purchase_paid||0)} · Balance ₩ ${money(a.purchase_outstanding||0)}</b></div></div><div class="card"><div class="section-title"><h3>Costs</h3>${a.lifecycle_stage!=='Sold / Completed'||me.role==='CEO / Owner'?`<button class="btn small" onclick="excavatorAddCost(${id})">+ Add Cost</button>`:''}</div>${costs.map(x=>`<div class="row"><span>${esc(x.type)}<small class="muted"> · ${esc(x.transaction_date||'')}</small></span><b>₩ ${money(x.amount)}</b></div>`).join('')||'<div class="muted">No additional costs yet.</div>'}<div class="row total"><span>Total machine cost</span><b>₩ ${money(totalCost)}</b></div></div><div class="card"><div class="section-title"><h3>Sale</h3><button class="btn small primary" onclick="excavatorSell(${id})">${a.lifecycle_stage==='Sold / Completed'?'Update Sale':'Sell Machine'}</button></div>${sale?`<div class="row"><span>Sale type</span><b>${esc((tx.find(x=>['Local Sale','Export Sale'].includes(x.type))||{}).type||'')}</b></div><div class="row"><span>Sale value</span><b>₩ ${money(sale)}</b></div><div class="row"><span>Customer</span><b>${esc(a.customer_name||'—')}</b></div><div class="row"><span>Payment status</span><b>${esc(paymentStatus)}</b></div>`:'<div class="muted">Machine has not been sold.</div>'}</div><div class="card"><div class="section-title"><h3>Recent History</h3></div>${hist.events.slice(0,8).map(x=>`<div class="row"><span>${esc(x.to_stage)}<small class="muted"> · ${esc(x.created_at)}</small></span><b>${esc(x.user_name||'')}</b></div>`).join('')||'<div class="muted">No stage changes yet.</div>'}</div></div>`)}

async function excavatorEditMachine(id){const a=(await api('/api/excavator/assets')).find(x=>x.id==id);if(!a)return;modal(`<h2>Edit Machine</h2><form onsubmit="saveExcavatorEdit(event,${id})"><div class="grid g3"><div class="field"><label>Machine / Deal No.</label><input name="asset_no" value="${esc(a.asset_no)}" required></div><div class="field"><label>Machine Name</label><input name="machine_name" value="${esc(a.machine_name||a.machine_display_name||"")}" required></div><div class="field"><label>Make</label><input name="make" value="${esc(a.make||'')}" required></div><div class="field"><label>Model</label><input name="model" value="${esc(a.model||'')}" required></div></div><div class="grid g3"><div class="field"><label>Year</label><input name="year" type="number" value="${a.year||''}"></div><div class="field"><label>Serial / Chassis</label><input name="serial_no" value="${esc(a.serial_no||'')}"></div><div class="field"><label>Purchase Price (KRW)</label><input name="purchase_price" type="number" step="1" value="${a.purchase_price||0}"></div></div><div class="field"><label>Notes</label><textarea name="notes">${esc(a.notes||'')}</textarea></div><div class="actions"><button type="button" class="btn" onclick="excavatorOpenMachine(${id})">Cancel</button><button class="btn primary">Save</button></div></form>`)}
async function saveExcavatorEdit(e,id){e.preventDefault();try{const o=Object.fromEntries(new FormData(e.target));await api('/api/excavator/assets/'+id,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(o)});closeModal();excavatorOpenMachine(id)}catch(x){toast(x.message)}}
async function excavatorAddCost(id){
  modal(`<h2>Add Cost</h2><p class="muted">Add logistics, repair, parts, customs, tax, shipping, commission or other costs. You can attach multiple supporting documents.</p><form onsubmit="saveSimpleExcavatorCost(event,${id})" enctype="multipart/form-data"><div class="grid g2"><div class="field"><label>Cost Type</label><select name="type"><option>Logistics</option><option>Repair</option><option>Part Purchase</option><option>Customs Duty</option><option>Tax / VAT</option><option>Shipping / Freight</option><option>Commission</option><option>Documentation / Clearance</option><option>Other Cost</option></select></div><div class="field"><label>Amount (KRW)</label><input name="amount" type="number" min="0" step="1" required></div></div><div class="grid g2"><div class="field"><label>Date</label><input name="transaction_date" type="date" required></div><div class="field"><label>Include in Machine Cost?</label><select name="include_cost"><option value="1">Yes</option><option value="0">No — Business Expense</option></select></div></div><div class="field"><label>Supplier / Payee</label><input name="counterparty"></div><div class="field"><label>Description</label><textarea name="notes" placeholder="e.g. transport from seller to yard, customs duty, repair work..."></textarea></div><div class="field"><label>Attachments</label><input name="files" type="file" multiple></div><div class="actions"><button type="button" class="btn" onclick="closeModal()">Cancel</button><button class="btn primary">Save Cost</button></div></form>`)
}
async function saveSimpleExcavatorCost(e,id){
  e.preventDefault();
  try{
    const fd=new FormData(e.target);
    fd.append('stage','Costs');
    fd.append('currency','KRW');
    fd.append('status','Open');
    fd.append('include_in_machine_cost',fd.get('include_cost')==='1'?'1':'0');
    const j=await multipartApi('/api/excavator/assets/'+id+'/transactions',fd);
    closeModal(); toast('Cost added'+(j.document_count?` with ${j.document_count} attachment(s)`:'')); excavatorOpenMachine(id);
  }catch(x){toast(x.message)}
}
async function excavatorSell(id){
  try{
    const [assets,buyers]=await Promise.all([api('/api/excavator/assets'),api('/api/excavator/buyers')]);
    const machine=assets.find(x=>x.id==id);if(!machine)return toast('Machine not found');
    const purchasePrice=Number(machine.purchase_price||0),purchasePaid=Number(machine.purchase_paid||0),outstanding=Math.max(0,purchasePrice-purchasePaid);
    if(outstanding>0){toast(`Cannot sell this machine until the complete purchase price is paid. Outstanding: ₩ ${money(outstanding)}`);return;}
    const closed=machine.lifecycle_stage==='Sold / Completed';let existing=null;
    if(closed){const r=await api('/api/excavator/assets/'+id+'/sale');existing=r?.sale||null;if(!existing)return toast('This machine is Sold / Completed but no editable sale record was found. Please inspect its history.');}
    const today=new Date().toISOString().slice(0,10),sale=existing||{},isUpdate=!!existing;
    const saleType=sale.sale_type||'Local Sale',saleDate=sale.sale_date||today,buyerId=sale.buyer_id||'',sellingPrice=sale.selling_price??machine.selling_price??'',paymentCurrency=sale.payment_currency||'KRW',paymentFx=Number(sale.payment_fx_rate||1)||1,paymentDate=sale.payment_date||today,paymentMethod=sale.payment_method||'Bank';
    modal(`<h2>${isUpdate?'Update Sale':'Sell Machine'} · ${esc(machine.asset_no)}</h2><p class="muted">${isUpdate?'The existing sale record is loaded below. Saving updates the same sale, its linked Finance record and sale document — no duplicate sale or Finance entry is created.':'100% sale payment is taken in advance. Existing buyer advance will be allocated to this machine. A new buyer will be added automatically after sale completion.'}</p><form id="excavatorSaleForm" onsubmit="completeExcavatorSale(event,${id})"><input type="hidden" name="sale_update" value="${isUpdate?'1':'0'}"><div class="grid g2"><div class="field"><label>Sale Type *</label><select name="sale_type" required onchange="toggleExcavatorExportFields(this.value)"><option value="Local Sale" ${saleType==='Local Sale'?'selected':''}>Local Sale</option><option value="Export Sale" ${saleType==='Export Sale'?'selected':''}>Export Sale</option></select></div><div class="field"><label>Sale Date *</label><input name="sale_date" type="date" value="${esc(saleDate)}" required></div></div><div class="field"><label>Buyer Record</label><select name="buyer_id" id="exBuyerSelect" onchange="fillExcavatorBuyer(this.value)"><option value="">+ New Buyer / Other</option>${buyers.map(b=>`<option value="${b.id}" ${String(b.id)===String(buyerId)?'selected':''}>${esc(b.name)} · ${esc(b.country||'')} · ${esc(b.buyer_type||'International')} · Available ₩ ${money(b.unallocated_advance_krw||0)}</option>`).join('')}</select></div><div id="exExistingBuyer" class="card" style="display:none"><div class="section-title"><h3>Selected Buyer Details</h3><span class="pill good" id="exBuyerBalance"></span></div><div class="grid g3"><div class="field"><label>Buyer / Company</label><input id="exExistingName" readonly></div><div class="field"><label>Buyer Type</label><input id="exExistingType" readonly></div><div class="field"><label>Country</label><input id="exExistingCountry" readonly></div><div class="field"><label>Location</label><input id="exExistingLocation" readonly></div><div class="field"><label>Contact Person</label><input id="exExistingContact" readonly></div><div class="field"><label>Phone</label><input id="exExistingPhone" readonly></div><div class="field"><label>WhatsApp</label><input id="exExistingWhatsapp" readonly></div><div class="field"><label>Email</label><input id="exExistingEmail" readonly></div><div class="field"><label>Address</label><input id="exExistingAddress" readonly></div></div></div><div id="exNewBuyer"><div class="grid g3"><div class="field"><label>Buyer / Company Name *</label><input name="new_buyer_name" id="exNewBuyerName"></div><div class="field"><label>Buyer Type *</label><select name="new_buyer_type"><option>International</option><option>Local</option></select></div><div class="field"><label>Country *</label><input name="new_buyer_country" id="exNewBuyerCountry"></div><div class="field"><label>Location / City</label><input name="new_buyer_location"></div><div class="field"><label>Contact Person</label><input name="new_buyer_contact_person"></div><div class="field"><label>Phone</label><input name="new_buyer_phone"></div><div class="field"><label>WhatsApp</label><input name="new_buyer_whatsapp"></div><div class="field"><label>Email</label><input name="new_buyer_email" type="email"></div><div class="field"><label>Payment Terms</label><input name="new_buyer_payment_terms"></div></div><div class="field"><label>Address</label><textarea name="new_buyer_address"></textarea></div><div class="field"><label>Notes</label><textarea name="new_buyer_notes"></textarea></div></div><div class="grid g2"><div class="field"><label>Customer / Buyer *</label><input id="exCustomerName" name="customer_name" placeholder="Customer / company name" value="${esc(sale.customer_name||'')}" required></div><div class="field"><label>Selling Price (KRW) *</label><input name="selling_price" type="number" min="1" step="1" required value="${esc(sellingPrice)}"></div></div><div id="exExportFields" style="display:none"><div class="grid g2"><div class="field"><label>Destination Country *</label><select name="destination_country" onchange="toggleOtherDestination(this.value)"><option value="Pakistan">Pakistan</option><option value="__OTHER__">Other Country</option></select></div><div class="field" id="exOtherCountryWrap" style="display:none"><label>Other Destination Country *</label><input name="other_destination_country"></div></div></div><div class="grid g2"><div class="field"><label>Shipping / Container Reference *</label><input name="shipping_reference" value="${esc(sale.shipping_reference||'')}" required></div><div class="field"><label>Payment Method *</label><select name="payment_method" required>${['Bank','Cash','Card','Other'].map(x=>`<option ${x===paymentMethod?'selected':''}>${x}</option>`).join('')}</select></div></div><div class="grid g3"><div class="field"><label>Payment Currency *</label><select name="payment_currency">${['KRW','USD','PKR'].map(x=>`<option ${x===paymentCurrency?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Conversion Rate to KRW *</label><input name="payment_fx_rate" type="number" step="0.000001" min="0.000001" value="${paymentFx}" required></div><div class="field"><label>Payment Date *</label><input name="payment_date" type="date" value="${esc(paymentDate)}" required></div></div><div class="field"><label>Payment Reference *</label><input name="payment_reference" value="${esc(sale.payment_reference||'')}" required autocomplete="off"></div><div class="field"><label>Notes (optional)</label><textarea name="notes">${esc(sale.notes||'')}</textarea></div><div class="field"><label>Sell Note (optional)</label><textarea name="sell_note">${esc(sale.sell_note||'')}</textarea></div><div class="actions"><button type="button" class="btn" onclick="closeModal()">Cancel</button><button type="submit" class="btn primary">${isUpdate?'Update Sale':'Complete Sale'}</button></div></form>`);
    toggleExcavatorExportFields(saleType);
    if(buyerId)await fillExcavatorBuyer(buyerId,{preserveSale:true,sale});else fillExcavatorBuyer('');
    if(saleType==='Export Sale')setExcavatorDestination(sale.destination_country||'Pakistan');
  }catch(e){toast(e.message)}
}
function isKoreanBuyer(b){const c=String(b?.country||'').trim().toLowerCase().replace(/\s+/g,' ');return String(b?.buyer_type||'').trim().toLowerCase()==='local'||['south korea','korea','republic of korea','korea, republic of','republic of korea (south korea)'].includes(c);}
function setExcavatorDestination(country){const select=document.querySelector('[name="destination_country"]'),other=document.querySelector('[name="other_destination_country"]');if(!select)return;const c=String(country||'').trim();if(!c||c.toLowerCase()==='pakistan'){select.value='Pakistan';if(other)other.value='';toggleOtherDestination('Pakistan');}else{select.value='__OTHER__';if(other)other.value=c;toggleOtherDestination('__OTHER__');}}
async function fillExcavatorBuyer(id,opts={}){const wrap=document.getElementById('exExistingBuyer'),nw=document.getElementById('exNewBuyer'),name=document.getElementById('exCustomerName');if(!id){if(wrap)wrap.style.display='none';if(nw)nw.style.display='block';if(name&&!opts.preserveSale)name.value='';return;}try{const d=await api('/api/excavator/buyers/'+id),b=d.buyer;if(wrap)wrap.style.display='block';if(nw)nw.style.display='none';if(name)name.value=opts?.sale?.customer_name||b.name;const set=(key,v)=>{const el=document.getElementById(key);if(el)el.value=v||''};set('exExistingName',b.name);set('exExistingType',b.buyer_type||'International');set('exExistingCountry',b.country);set('exExistingLocation',b.location);set('exExistingContact',b.contact_person);set('exExistingPhone',b.phone);set('exExistingWhatsapp',b.whatsapp);set('exExistingEmail',b.email);set('exExistingAddress',b.address);const bal=document.getElementById('exBuyerBalance');if(bal)bal.textContent=tr('buyer.availableAdvance',{amount:money(d.balance.available_advance_krw)});const autoType=isKoreanBuyer(b)?'Local Sale':'Export Sale',saleSelect=document.querySelector('#excavatorSaleForm [name="sale_type"]');if(saleSelect){saleSelect.value=opts.preserveSale&&opts.sale?.sale_type?opts.sale.sale_type:autoType;toggleExcavatorExportFields(saleSelect.value);if(saleSelect.value==='Export Sale')setExcavatorDestination(opts.preserveSale&&opts.sale?.destination_country?opts.sale.destination_country:b.country||'Pakistan');} }catch(e){toast(e.message)}}
function toggleExcavatorExportFields(value){const wrap=document.getElementById('exExportFields'),country=document.querySelector('[name="destination_country"]'),other=document.querySelector('[name="other_destination_country"]');if(wrap)wrap.style.display=value==='Export Sale'?'block':'none';if(country)country.required=value==='Export Sale';if(value!=='Export Sale'&&other){other.value='';other.required=false;}}
function toggleOtherDestination(value){const w=document.getElementById('exOtherCountryWrap'),other=document.querySelector('[name="other_destination_country"]');if(w)w.style.display=value==='__OTHER__'?'block':'none';if(other)other.required=value==='__OTHER__';}
async function completeExcavatorSale(e,id){e.preventDefault();const form=e.target;if(!form.reportValidity())return;const submit=form.querySelector('[type="submit"]'),original=submit?.textContent;if(submit){submit.disabled=true;submit.textContent=form.sale_update?.value==='1'?tr('common.updating'):tr('common.completing')}try{const fd=new FormData(form),o=Object.fromEntries(fd.entries());for(const k of Object.keys(o))if(typeof o[k]==='string')o[k]=o[k].trim();o.destination_country=o.sale_type==='Export Sale'?(o.destination_country==='__OTHER__'?o.other_destination_country:o.destination_country):'';if(!o.customer_name)throw new Error('Customer / Buyer is required.');const price=Number(o.selling_price);if(!Number.isFinite(price)||price<=0)throw new Error('Selling Price must be greater than zero.');if(!o.buyer_id){o.new_buyer_name=o.new_buyer_name||o.customer_name;o.new_buyer_country=o.new_buyer_country||o.destination_country;if(!o.new_buyer_name||!o.new_buyer_country)throw new Error('Complete new buyer name and country are required.');}const r=await api('/api/excavator/assets/'+id+'/complete-sale',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(o)});if(r.approval_required){toast(r.message||'Approval is required before this sale change can be applied.');if(submit){submit.disabled=false;submit.textContent=original}return;}closeModal();toast(r.updated?'Sale updated · Finance synchronized · Sale PDF updated':'Sale completed · Buyer and Finance synchronized · Sale PDF created');loadView();if(r.document_url)setTimeout(()=>window.open(r.document_url,'_blank'),250);}catch(x){if(submit){submit.disabled=false;submit.textContent=original}toast(x.message)}}
async function excavatorChangeStage(id){const a=(await api('/api/excavator/assets')).find(x=>x.id==id);modal(`<h2>Machine Status</h2><form onsubmit="saveSimpleStage(event,${id})"><div class="field"><label>Current stage</label><select name="stage">${['Purchased','Transport to Yard','In Yard','Under Repair','Ready for Sale','On Hold','Export Preparation','Cancelled'].map(x=>`<option ${a?.lifecycle_stage===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Note</label><textarea name="note"></textarea></div><div class="actions"><button type="button" class="btn" onclick="closeModal()">Cancel</button><button class="btn primary">Save Status</button></div></form>`)}
async function saveSimpleStage(e,id){e.preventDefault();try{const o=Object.fromEntries(new FormData(e.target));await api('/api/excavator/assets/'+id+'/stage',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(o)});closeModal();toast('Status saved');excavatorOpenMachine(id)}catch(x){toast(x.message)}}
async function excavatorPayments(id){
  const p=await api('/api/excavator/assets/'+id+'/payments');
  modal(`<h2>Payments</h2><p class="muted">Record purchase or sale payments. Incorrect records can be deleted.</p><button class="btn primary" onclick="excavatorPaymentForm(${id})">+ Add Payment</button><div class="table-wrap" style="margin-top:12px"><table class="table"><tr><th>Type</th><th>Amount</th><th>Status</th><th>Date</th><th>Method</th><th>Reference</th><th>Receipt</th><th></th></tr>${p.map(x=>`<tr><td>${esc(x.payment_type)}</td><td>₩ ${money(x.amount)}</td><td>${esc(x.status)}</td><td>${esc(x.paid_date||x.due_date||'—')}</td><td>${esc(x.method)}</td><td>${esc(x.reference||'')}</td><td>${x.receipt_url?`<a class="btn small" target="_blank" href="${esc(x.receipt_url)}">Receipt</a>`:'—'}</td><td><button class="btn small danger" onclick="deleteExcavatorPayment(${id},${x.id})">Delete</button></td></tr>`).join('')||'<tr><td colspan="8">No payments yet.</td></tr>'}</table></div>`)
}
async function deleteExcavatorPayment(assetId,paymentId){
  const reason=await reasonAction({title:'Request Machine Payment Void',message:'The payment and linked Finance record will remain traceable in audit history.',confirmLabel:'Request Void',tone:'danger',details:[{label:'Payment',value:'#'+paymentId},{label:'Machine / Deal',value:'#'+assetId}],placeholder:'Reason for voiding this payment'});if(reason===null)return;
  try{const r=await api('/api/excavator/assets/'+assetId+'/payments/'+paymentId,{method:'DELETE',headers:{'Content-Type':'application/json'},body:JSON.stringify({reason:reason.trim()})});if(r.approval_required)return toast(r.message||'Payment void submitted for approval');toast('Payment voided and Finance updated');excavatorPayments(assetId)}catch(x){toast(x.message)}
}
async function excavatorPaymentForm(id){modal(`<h2>Add Payment</h2><form onsubmit="saveExcavatorPayment(event,${id})" enctype="multipart/form-data"><div class="grid g3"><div class="field"><label>Payment For</label><select name="payment_type"><option>Purchase</option><option>Sale</option></select></div><div class="field"><label>Amount (KRW)</label><input name="amount" type="number" min="0" step="1" required></div><div class="field"><label>Payment Date</label><input name="payment_date" type="date" required></div></div><div class="grid g3"><div class="field"><label>Method</label><select name="method"><option>Bank</option><option>Cash</option><option>Card</option><option>Other</option></select></div><div class="field"><label>Reference</label><input name="reference" required placeholder="Required"></div><div class="field"><label>Payment Receipt</label><input name="receipt" type="file" multiple accept="application/pdf,image/*"></div></div><div class="field"><label>Notes</label><textarea name="notes"></textarea></div><div class="actions"><button type="button" class="btn" onclick="closeModal()">Cancel</button><button class="btn primary">Save Payment</button></div></form>`)}
async function saveExcavatorPayment(e,id){e.preventDefault();try{const fd=new FormData(e.target);if(!fd.get('payment_date'))throw new Error('Payment Date is required.');if(!String(fd.get('reference')||'').trim())throw new Error('Reference is required.');const j=await multipartApi('/api/excavator/assets/'+id+'/payments',fd);toast(j.receipt_document_id?'Payment saved and receipt added to Documents':'Payment saved');scheduleDataSync();excavatorPayments(id)}catch(x){toast(x.message)}}

async function excavatorDocuments(id){const docs=await api('/api/excavator/assets/'+id+'/documents');modal(`<h2>Documents</h2><p class="muted">Attach multiple files now or later. Previous documents are never replaced.</p><form onsubmit="uploadExcavatorDocuments(event,${id})" enctype="multipart/form-data"><div class="grid g2"><div class="field"><label>Stage</label><select name="stage">${['Purchase','Costs','Repair','Parts','Local Sale','Export Preparation','Export/Shipping','Payment','General'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>Files</label><input name="files" type="file" multiple required></div></div><div class="actions"><button class="btn primary">Upload Documents</button></div></form><div class="table-wrap" style="margin-top:12px"><table class="table"><tr><th>Stage</th><th>File</th><th>Date</th><th>Open</th></tr>${docs.map(d=>`<tr><td>${esc(d.stage)}</td><td>${esc(d.original_name)}</td><td>${esc(d.created_at)}</td><td><a class="btn small" href="${esc(d.file_path)}" target="_blank">Open</a></td></tr>`).join('')||'<tr><td colspan="4">No documents yet.</td></tr>'}</table></div>`)}
async function uploadExcavatorDocuments(e,id){e.preventDefault();try{const j=await multipartApi('/api/excavator/assets/'+id+'/documents',new FormData(e.target));toast(j.count+' document(s) uploaded');scheduleDataSync();excavatorDocuments(id)}catch(x){toast(x.message)}}
async function deleteExcavatorAsset(id){const ok=await confirmAction({title:'Delete Machine / Deal',message:'This is a high-impact action. The backend will block deletion when protected history must be retained.',confirmLabel:'Delete Machine',tone:'danger',details:[{label:'Machine / Deal',value:'#'+id}]});if(!ok)return;try{await api('/api/excavator/assets/'+id,{method:'DELETE'});toast('Machine deleted');loadView()}catch(x){toast(x.message)}}
async function restaurantPOS(){const [p,t]=await Promise.all([api('/api/products'),api('/api/restaurant/tables')]);const menu=p.filter(x=>x.business_unit==='MIMI Resturant');window._rItems=[];modal(`<div class="section-title"><h2>MIMI Resturant POS</h2></div><div class="pos-layout"><div><div class="grid g3"><div class="field"><label>Order type</label><select id="rType"><option>Dine-in</option><option>Takeaway</option><option>Delivery</option></select></div><div class="field"><label>Table</label><select id="rTable"><option value="">No table</option>${t.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></div><div class="field"><label>Customer</label><input id="rCustomer"></div></div><div class="menu-grid">${menu.map(x=>`<button type="button" class="menu-item" onclick="addRItem(${x.id})"><b>${esc(x.name)}</b><div class="muted">${x.item_type} · ${money(x.selling_price)}</div></button>`).join('')}</div></div><div class="card"><h3>Order</h3><div id="rCart"></div><div class="field"><label>Payment</label><select id="rPayment"><option>Cash</option><option>Card</option><option>Bank</option><option>Credit</option></select></div><div class="actions"><button type="button" class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveROrder()">Close & Pay</button></div></div></div>`);window._rProducts=menu;drawR()}
function addRItem(id){const p=window._rProducts.find(x=>x.id==id),x=window._rItems.find(x=>x.product_id==id);if(x)x.quantity++;else window._rItems.push({product_id:p.id,name:p.name,quantity:1,unit_price:p.selling_price});drawR()}
function drawR(){const e=document.getElementById('rCart');if(!e)return;e.innerHTML=window._rItems.length?window._rItems.map((x,i)=>`<div class="cart-row"><span>${esc(x.name)}</span><span><input style="width:55px" type="number" min="0.01" step="0.01" value="${x.quantity}" onchange="window._rItems[${i}].quantity=Number(this.value);drawR()"> × <input style="width:85px" type="number" min="0" step="0.01" value="${x.unit_price}" onchange="window._rItems[${i}].unit_price=Number(this.value);drawR()"> = <b>${money(x.quantity*x.unit_price)}</b> <button class="btn small" onclick="window._rItems.splice(${i},1);drawR()">×</button></span></div>`).join(''):'<span class="muted">Empty order</span>'}
async function saveROrder(){if(!window._rItems.length)return toast('Add menu items');try{const d=await api('/api/restaurant/orders',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({table_id:document.getElementById('rTable').value,order_type:document.getElementById('rType').value,customer_name:document.getElementById('rCustomer').value,items:window._rItems})});const pay=document.getElementById('rPayment').value;await api('/api/restaurant/orders/'+d.id+'/close',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({payment_method:pay})});closeModal();toast('MIMI order closed and posted to sales/finance/inventory');loadView();printReceipt(d.id)}catch(x){toast(x.message)}}
async function manageRestaurantTables(){try{const t=await api('/api/restaurant/tables');modal(`<div class="section-title"><h2>MIMI Tables</h2><button class="btn primary" onclick="tableForm()">+ Add Table</button></div><p class="muted">Delete Table is available for tables that are not Busy and have no open order.</p><div class="table-wrap"><table class="table"><tr><th>Table</th><th>Capacity</th><th>Status</th><th>Actions</th></tr>${t.map(x=>`<tr><td>${esc(x.name)}</td><td>${x.capacity}</td><td><span class="pill ${x.status==='Available'?'good':x.status==='Busy'?'bad':'warn'}">${esc(x.status)}</span></td><td><button class="btn small" onclick="tableForm(${x.id})">Edit</button> <button class="btn small danger" onclick="deleteTable(${x.id},true)">Delete Table</button></td></tr>`).join('')}</table></div>${!t.length?'<p class="muted">No restaurant tables configured.</p>':''}`)}catch(x){toast(x.message)}}

async function tableForm(id){const t=id?(await api('/api/restaurant/tables')).find(x=>x.id==id):null;modal(`<h2>${id?'Edit':'Add'} restaurant table</h2><form onsubmit="saveTable(event,${id||0})"><div class="grid g2"><div class="field"><label>Table name</label><input name="name" value="${esc(t?.name||'')}" required></div><div class="field"><label>Capacity</label><input name="capacity" type="number" value="${t?.capacity||4}"></div></div><div class="field"><label>Status</label><select name="status"><option ${t?.status==='Available'?'selected':''}>Available</option><option ${t?.status==='Busy'?'selected':''}>Busy</option><option ${t?.status==='Reserved'?'selected':''}>Reserved</option></select></div><div class="actions"><button type="button" class="btn" onclick="closeModal()">Cancel</button><button class="btn primary">${id?'Update':'Add'}</button></div></form>`)}
