async function wasteForm(){const p=(await api('/api/products')).filter(x=>x.business_unit==='MIMI Resturant'&&x.item_type==='PRODUCT');modal(`<h2>MIMI waste</h2><form onsubmit="saveWaste(event)"><div class="field"><label>Item</label><select name="product_id">${p.map(x=>`<option value="${x.id}">${esc(x.name)} (${x.current_stock})</option>`).join('')}</select></div><div class="field"><label>Quantity</label><input name="quantity" type="number" step="0.01" required></div><div class="field"><label>Reason</label><input name="reason" placeholder="Spoilage, damage, expired..."></div><div class="actions"><button type="button" class="btn" onclick="closeModal()">Cancel</button><button class="btn primary">Record waste</button></div></form>`)}
