function closingForm(){modal(`<h2>MIMI daily closing</h2><form onsubmit="saveClosing(event)"><div class="grid g2"><div class="field"><label>Business date</label><input name="business_date" type="date" value="${new Date().toISOString().slice(0,10)}"></div><div class="field"><label>Cash counted</label><input name="cash_counted" type="number" step="0.01"></div></div><div class="field"><label>Notes</label><textarea name="notes"></textarea></div><div class="actions"><button type="button" class="btn" onclick="closeModal()">Cancel</button><button class="btn primary">Close day</button></div></form>`)}
