async function readNotif(id){await api('/api/notifications/'+id+'/read',{method:'PUT'});await Promise.allSettled([refreshNotifCount(),refreshActionCounts()]);if(document.getElementById('notifDialog')){closeNotifDialog();await toggleNotifs()}if(view==='notifications')await refreshCurrentView({preserve:true})}
async function printReceipt(id){try{const s=await api('/api/sales/'+id);const w=window.open('','_blank','width=420,height=700');if(!w)return toast('Please allow pop-ups to print the receipt');const lang=currentLanguage==='ko'?'ko':'en';w.document.write(`<html lang="${lang}"><head><meta charset="utf-8"><title>${esc(s.invoice_no)}</title><style>body{font-family:"Noto Sans KR","Malgun Gothic",Arial,sans-serif;width:80mm;margin:0;padding:12px;font-size:12px;word-break:keep-all}h2{text-align:center;margin:0 0 4px}.center{text-align:center}.line{border-top:1px dashed #333;margin:8px 0}.row{display:flex;justify-content:space-between;gap:12px;margin:4px 0}.row span:last-child{text-align:right}.total{font-size:16px;font-weight:bold}.muted{color:#666}.empty{padding:28px;text-align:center;color:#64748b}.notif{padding:12px;border:1px solid #e2e8f0;border-radius:10px} .stat .value{font-size:28px;font-weight:800}</style></head><body><h2>${esc(t('BLUE OCEAN MARKET'))}</h2><div class=center>${esc(t(s.business_unit))}</div><div class=center>${esc(s.invoice_no)} · ${esc(s.created_at)}</div><div class=line></div>${s.items.map(i=>`<div class=row><span>${esc(i.item_name)} × ${i.quantity}</span><span>${money(i.line_total)}</span></div>`).join('')}<div class=line></div><div class=row><span>${esc(t('Subtotal'))}</span><span>${money(s.subtotal)}</span></div><div class=row><span>${esc(t('Discount'))}</span><span>${money(s.discount)}</span></div><div class=row><span>${esc(t('Tax'))}</span><span>${money(s.tax)}</span></div><div class=row total><span>${esc(t('Total'))}</span><span>${money(s.total)}</span></div><div class=row><span>${esc(t('Payment'))}</span><span>${esc(t(s.payment_method))}</span></div><div class=line></div><div class=center>${esc(t('Thank you'))}</div><script>window.onload=()=>{window.print();setTimeout(()=>window.close(),500)}<\/script></body></html>`);w.document.close()}catch(x){toast(x.message)}}

async function purchaseEdit(id){const rows=await api('/api/purchases'),x=rows.find(z=>z.id==id);if(!x)return;modal(`<h2>Edit purchase</h2><form onsubmit="savePurchaseEdit(event,${id})"><div class="field"><label>Supplier</label><input name="supplier_name" value="${esc(x.supplier_name||'')}"></div><div class="grid g2"><div class="field"><label>Payment</label><select name="payment_method"><option>Cash</option><option>Card</option><option>Bank</option><option>Credit</option></select></div><div class="field"><label>Status</label><select name="status"><option>Posted</option><option>Voided</option></select></div></div><div class="field"><label>Notes</label><textarea name="notes">${esc(x.notes||'')}</textarea></div><div class="actions"><button type="button" class="btn" onclick="closeModal()">Cancel</button><button class="btn primary">Update</button></div></form>`)}
async function savePurchaseEdit(e,id){e.preventDefault();const o=Object.fromEntries(new FormData(e.target));const ok=await confirmAction({title:'Update Purchase',message:'Updating a purchase also synchronizes its linked Finance source record. No duplicate Finance entry should be created.',confirmLabel:'Update Purchase',details:[{label:'Purchase',value:'#'+id},{label:'Supplier',value:o.supplier_name||''},{label:'Amount',value:o.total?'₩ '+money(o.total):''}]});if(!ok)return;try{await api('/api/purchases/'+id,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(o)});closeModal(true);toast('Purchase updated and Finance synchronized');loadView()}catch(x){toast(x.message)}}
async function voidPurchase(id){const rows=await api('/api/purchases'),x=rows.find(z=>Number(z.id)===Number(id));const reason=await reasonAction({title:'Request Purchase Void',message:'This request preserves purchase history and reverses linked Finance effects only after the applicable approval workflow.',confirmLabel:'Request Void',tone:'danger',details:[{label:'Purchase',value:x?.purchase_no||('#'+id)},{label:'Supplier',value:x?.supplier_name||''},{label:'Amount',value:x?money(x.total):''}],placeholder:'Reason for voiding this purchase'});if(reason===null)return;try{const r=await api('/api/purchases/'+id,{method:'DELETE',headers:{'Content-Type':'application/json'},body:JSON.stringify({reason:reason.trim()})});if(r.approval_required)return toast(r.message||'Purchase void submitted for approval');toast('Purchase voided');loadView()}catch(x){toast(x.message)}}
async function financeEdit(id){const rows=await api('/api/finance'),x=rows.find(z=>z.id==id);if(!x)return;modal(`<h2>Edit finance entry</h2><form onsubmit="saveFinanceEdit(event,${id})"><div class="grid g2"><div class="field"><label>Type</label><select name="type"><option ${x.type==='Expense'?'selected':''}>Expense</option><option ${x.type==='Revenue'?'selected':''}>Revenue</option></select></div><div class="field"><label>Amount</label><input name="amount" type="number" step="0.01" value="${x.amount}"></div></div><div class="grid g2"><div class="field"><label>Category</label><input name="category" value="${esc(x.category||'')}"></div><div class="field"><label>Payment</label><select name="payment_method"><option>Cash</option><option>Card</option><option>Bank</option><option>Credit</option><option>Other</option></select></div></div><div class="field"><label>Description</label><textarea name="description">${esc(x.description||'')}</textarea></div><div class="actions"><button type="button" class="btn" onclick="closeModal()">Cancel</button><button class="btn primary">Update</button></div></form>`)}
