async function voidFinance(id){const d=await api('/api/finance/'+id+'/detail');const f=d.finance;const reason=await reasonAction({title:'Request Finance Void',message:'The Finance record will remain in audit history. The financial effect is removed only after the configured approval workflow.',confirmLabel:'Request Void',tone:'danger',details:[{label:'Finance Record',value:'#'+id},{label:'Source',value:d.source?.label||f.source_type||'Manual'},{label:'Amount',value:'₩ '+money(f.krw_amount||f.amount)},{label:'Reference',value:f.reference||'—'}],placeholder:'Reason for voiding this Finance record'});if(reason===null)return;try{const r=await api('/api/finance/'+id,{method:'DELETE',headers:{'Content-Type':'application/json'},body:JSON.stringify({reason:reason.trim()})});if(r.approval_required)return toast(r.message||'Finance void submitted for approval');toast('Finance entry voided');loadView()}catch(x){toast(x.message)}}
