async function userActivate(id){const ok=await confirmAction({title:'Activate User',message:'Activate this user while keeping the existing business-unit assignment.',confirmLabel:'Activate',details:[{label:'User',value:'#'+id}]});if(!ok)return;try{await api('/api/users/'+id,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({active:1})});toast('User activated; business assignment preserved');loadView()}catch(x){toast(x.message)}}
async function userPermanentDelete(id){if(me.role!=='CEO / Owner')return toast('Only CEO can permanently delete profiles');const rows=await api('/api/users');const u=rows.find(x=>x.id==id);if(!u)return toast('User not found');const ok=await confirmAction({title:'Permanently Delete User Profile',message:'This action cannot be undone. Historical business activity should remain auditable according to backend safeguards.',confirmLabel:'Delete Profile',tone:'danger',details:[{label:'User',value:u.name},{label:'Email',value:u.email},{label:'Business Unit',value:u.business_unit||'All / Company'}]});if(!ok)return;try{await api('/api/users/'+id,{method:'DELETE'});toast('User profile permanently deleted');loadView()}catch(x){toast(x.message)}}

// V8/V9 restaurant experience: MIMI dashboard, menu, stock, weekly menu, buffet, open orders and advanced table workflow.
async function restaurant(c){
 const [d,t,o,m,w,b]=await Promise.all([api('/api/restaurant/dashboard'),api('/api/restaurant/tables'),api('/api/restaurant/orders'),api('/api/restaurant/menu'),api('/api/restaurant/weekly-menu'),api('/api/restaurant/buffets')]);
 const tabs=`<div class="actions" style="flex-wrap:wrap"><button class="btn primary" onclick="restaurantPOS()">Open POS</button><button class="btn" onclick="restaurantMenu()">Menu</button><button class="btn" onclick="restaurantStock()">Stock</button><button class="btn" onclick="restaurantWeekly()">Weekly Menu</button><button class="btn" onclick="restaurantBuffet()">Buffet</button><button class="btn" onclick="restaurantOpenOrders()">Open Orders</button><button class="btn" onclick="advancedRestaurantSettings()">Advanced POS</button><button class="btn" onclick="wasteForm()">Waste</button><button class="btn" onclick="closingForm()">Daily Closing</button></div>`;
 const tc=(d.tables||[]).map(x=>`<span class="pill ${x.status==='Available'?'good':x.status==='Busy'?'bad':'warn'}">${esc(x.status)} ${x.count}</span>`).join(' ');
 c.innerHTML=title('MIMI Resturant · Business Dashboard','Complete restaurant workspace — POS, menu, stock, weekly menu, buffet and open-order control',tabs)+`<div class="grid g4"><div class="card"><div class="muted">Today Sales</div><div class="kpi-value">${money(d.sales.total)}</div><div class="muted">${d.sales.count} completed sales</div></div><div class="card"><div class="muted">Gross Profit</div><div class="kpi-value">${money(d.sales.profit)}</div></div><div class="card"><div class="muted">Open Orders</div><div class="kpi-value">${d.open.count}</div></div><div class="card"><div class="muted">Stock Value</div><div class="kpi-value">${money(d.stock.value)}</div><div class="muted">${d.stock.low} low-stock items</div></div></div><div class="grid g2" style="margin-top:16px"><div class="card"><div class="section-title"><h3>Restaurant Tables</h3><div class="actions" style="margin:0"><button class="btn small" onclick="manageRestaurantTables()">Manage Tables</button></div></div><div class="room">${t.map(x=>`<div class="table-tile ${x.status==='Busy'?'busy':''}"><b>${esc(x.name)}</b><div class="muted">${x.capacity} seats</div><span class="pill ${x.status==='Available'?'good':x.status==='Busy'?'bad':'warn'}">${x.status}</span>${x.status==='Busy'?`<button class="btn small" onclick="restaurantOpenOrders(${x.id})">Open order</button>`:''}<button class="btn small" onclick="tableForm(${x.id})">Edit</button></div>`).join('')}</div><div style="margin-top:10px">${tc}</div></div><div class="card"><div class="section-title"><h3>Quick Restaurant Setup</h3></div><div class="grid g2"><button class="btn" onclick="menuForm()">+ Menu Item</button><button class="btn" onclick="stockForm()">+ Stock Movement</button><button class="btn" onclick="weeklyForm()">+ Weekly Menu</button><button class="btn" onclick="buffetForm()">+ Buffet</button></div><div class="muted" style="margin-top:12px">Menu items are connected to MIMI products and POS. Stock movements feed inventory and low-stock alerts.</div></div></div><div class="grid g3" style="margin-top:16px"><div class="card"><h3>Menu</h3><div class="muted">${m.filter(x=>x.active).length} active items</div>${m.slice(0,6).map(x=>`<div class="row"><span>${esc(x.name)}</span><b>${money(x.price)}</b></div>`).join('')}</div><div class="card"><h3>Weekly Menu</h3><div class="muted">${w.filter(x=>x.published).length} published entries</div>${w.slice(0,6).map(x=>`<div class="row"><span>${esc(x.menu_date)}</span><span>${esc(x.menu_name)}</span></div>`).join('')}</div><div class="card"><h3>Buffets</h3>${b.slice(0,6).map(x=>`<div class="row"><span>${esc(x.name)}</span><span>${esc(x.status)} · ${money(x.price)}</span></div>`).join('')||'<div class="muted">No buffets</div>'}</div></div>`;
}
async function restaurantMenu(){const m=await api('/api/restaurant/menu');modal(`<h2>MIMI Menu Management</h2><div class="actions"><button class="btn primary" onclick="menuForm()">+ Add Menu Item</button></div><div class="table-wrap"><table class="table"><tr><th>Name</th><th>Category</th><th>Price</th><th>Available</th><th>Stock</th><th>Actions</th></tr>${m.map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.category)}</td><td>${money(x.price)}</td><td>${x.available?'Yes':'No'}</td><td>${x.item_type==='PRODUCT'?x.current_stock:'—'}</td><td><button class="btn small" onclick="menuForm(${x.id})">Edit</button> <button class="btn small" onclick="menuItemStockForm(${x.id})">Update Stock</button> <button class="btn small" onclick="recipeForm(${x.id})">Ingredients / Recipe</button> <button class="btn small danger" onclick="deleteMenu(${x.id})">Archive</button></td></tr>`).join('')}</table></div>`)}
async function menuForm(id){const [m,p]=await Promise.all([api('/api/restaurant/menu'),api('/api/products')]);const x=id?m.find(z=>z.id==id):null;const ps=p.filter(z=>z.business_unit==='MIMI Resturant'&&(z.active||z.id===x?.product_id));modal(`<h2>${id?'Edit':'Add'} MIMI menu item</h2><form onsubmit="saveMenu(event,${id||0})"><div class="grid g2"><div class="field"><label>Product</label><select name="product_id" ${id?'disabled':''}>${ps.map(z=>`<option value="${z.id}" ${x?.product_id==z.id?'selected':''}>${esc(z.name)}</option>`).join('')}</select></div><div class="field"><label>Menu name</label><input name="name" value="${esc(x?.name||'')}"></div></div><div class="grid g4"><div class="field"><label>Category</label><select name="category">${['Breakfast','Main Course','Fast Food','Beverage','Dessert','Buffet','Other'].map(z=>`<option ${x?.category===z?'selected':''}>${z}</option>`).join('')}</select></div><div class="field"><label>Price</label><input name="price" type="number" step="0.01" value="${x?.price||0}"></div><div class="field"><label>Availability</label><select name="available"><option value="1" ${x?.available?'selected':''}>Available</option><option value="0" ${x&&!x.available?'selected':''}>Unavailable</option></select></div><div class="field"><label>Menu Status</label><select name="active"><option value="1" ${!x||x.active?'selected':''}>Active / Available in POS</option><option value="0" ${x&&!x.active?'selected':''}>Archived</option></select></div></div><div class="field"><label>Description</label><textarea name="description">${esc(x?.description||'')}</textarea></div><div class="actions"><button type="button" class="btn" onclick="closeModal()">Cancel</button><button class="btn primary">Save</button></div></form>`)}
async function saveMenu(e,id){e.preventDefault();const o=Object.fromEntries(new FormData(e.target));try{await api(id?'/api/restaurant/menu/'+id:'/api/restaurant/menu',{method:id?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(o)});closeModal();restaurantMenu()}catch(x){toast(x.message)}}
async function deleteMenu(id){const ok=await confirmAction({title:'Archive Menu Item',message:'Archive this menu item so it is no longer available in POS.',confirmLabel:'Archive',tone:'danger',details:[{label:'Menu Item',value:'#'+id}]});if(!ok)return;try{await api('/api/restaurant/menu/'+id,{method:'DELETE'});restaurantMenu()}catch(x){toast(x.message)}}
async function restaurantStock(){const p=(await api('/api/products')).filter(x=>x.business_unit==='MIMI Resturant'&&x.item_type==='PRODUCT');modal(`<h2>MIMI Stock Management</h2><button class="btn primary" onclick="stockForm()">+ Stock Movement</button><div class="table-wrap" style="margin-top:12px"><table class="table"><tr><th>Item</th><th>Stock</th><th>Reorder</th><th>Cost</th><th>Value</th></tr>${p.map(x=>`<tr><td>${esc(x.name)}</td><td>${x.current_stock}</td><td>${x.reorder_level}</td><td>${money(x.cost_price)}</td><td>${money(x.current_stock*x.cost_price)}</td></tr>`).join('')}</table></div>`)}
async function stockForm(){const p=(await api('/api/products')).filter(x=>x.business_unit==='MIMI Resturant'&&x.item_type==='PRODUCT');modal(`<h2>Stock Movement</h2><form onsubmit="saveRestaurantStock(event)"><div class="field"><label>Item</label><select name="product_id">${p.map(x=>`<option value="${x.id}">${esc(x.name)} — ${x.current_stock} in stock</option>`).join('')}</select></div><div class="grid g2"><div class="field"><label>Movement</label><select name="type"><option value="RECEIVE">Receive</option><option value="ISSUE">Issue</option><option value="ADJUST">Adjustment In</option><option value="WASTE">Waste</option></select></div><div class="field"><label>Quantity</label><input name="quantity" type="number" min="0.01" step="0.01" required></div></div><div class="field"><label>Reason</label><textarea name="reason"></textarea></div><div class="actions"><button type="button" class="btn" onclick="closeModal()">Cancel</button><button class="btn primary">Save</button></div></form>`)}
async function saveRestaurantStock(e){e.preventDefault();try{await api('/api/restaurant/stock',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});closeModal();restaurantStock()}catch(x){toast(x.message)}}
async function restaurantWeekly(){const w=await api('/api/restaurant/weekly-menu');modal(`<h2>MIMI Weekly Menu</h2><button class="btn primary" onclick="weeklyForm()">+ Add Entry</button><div class="table-wrap" style="margin-top:12px"><table class="table"><tr><th>Date</th><th>Meal</th><th>Menu Item</th><th>Published</th><th>Actions</th></tr>${w.map(x=>`<tr><td>${esc(x.menu_date)}</td><td>${esc(x.meal_period)}</td><td>${esc(x.menu_name)}</td><td>${x.published?'Yes':'No'}</td><td><button class="btn small" onclick="weeklyForm(${x.id})">Edit</button> <button class="btn small danger" onclick="deleteWeekly(${x.id})">Delete</button></td></tr>`).join('')}</table></div>`)}
async function weeklyForm(){const m=await api('/api/restaurant/menu');modal(`<h2>Add Weekly Menu</h2><form onsubmit="saveWeekly(event)"><div class="grid g3"><div class="field"><label>Date</label><input name="menu_date" type="date" required></div><div class="field"><label>Meal period</label><select name="meal_period"><option>All Day</option><option>Breakfast</option><option>Lunch</option><option>Dinner</option></select></div><div class="field"><label>Menu item</label><select name="menu_item_id">${m.filter(x=>x.active&&x.available).map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></div></div><div class="field"><label>Published</label><select name="published"><option value="1">Publish</option><option value="0">Draft</option></select></div><div class="field"><label>Notes</label><textarea name="notes"></textarea></div><div class="actions"><button type="button" class="btn" onclick="closeModal()">Cancel</button><button class="btn primary">Save</button></div></form>`)}
async function saveWeekly(e){e.preventDefault();try{await api('/api/restaurant/weekly-menu',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});closeModal();restaurantWeekly()}catch(x){toast(x.message)}}
async function deleteWeekly(id){const ok=await confirmAction({title:'Delete Weekly Menu Entry',message:'Remove this weekly menu schedule entry?',confirmLabel:'Delete',tone:'danger',details:[{label:'Entry',value:'#'+id}]});if(!ok)return;await api('/api/restaurant/weekly-menu/'+id,{method:'DELETE'});restaurantWeekly()}
async function restaurantBuffet(){const b=await api('/api/restaurant/buffets');modal(`<h2>MIMI Buffet Management</h2><button class="btn primary" onclick="buffetForm()">+ Create Buffet</button><div class="table-wrap" style="margin-top:12px"><table class="table"><tr><th>Buffet</th><th>Date</th><th>Time</th><th>Price</th><th>Capacity</th><th>Status</th><th>Actions</th></tr>${b.map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.buffet_date)}</td><td>${esc(x.start_time)}–${esc(x.end_time)}</td><td>${money(x.price)}</td><td>${x.capacity||'Unlimited'}</td><td>${esc(x.status)}</td><td><button class="btn small" onclick="buffetForm(${x.id})">Edit</button> <button class="btn small danger" onclick="deleteBuffet(${x.id})">Delete</button></td></tr>`).join('')}</table></div>`)}
async function buffetForm(id){const [b,m]=await Promise.all([api('/api/restaurant/buffets'),api('/api/restaurant/menu')]);const x=id?b.find(z=>z.id==id):null;modal(`<h2>${id?'Edit':'Create'} Buffet</h2><form onsubmit="saveBuffet(event,${id||0})"><div class="grid g2"><div class="field"><label>Name</label><input name="name" value="${esc(x?.name||'Friday Buffet')}" required></div><div class="field"><label>Date</label><input name="buffet_date" type="date" value="${x?.buffet_date||''}" required></div></div><div class="grid g3"><div class="field"><label>Start</label><input name="start_time" type="time" value="${x?.start_time||''}"></div><div class="field"><label>End</label><input name="end_time" type="time" value="${x?.end_time||''}"></div><div class="field"><label>Price</label><input name="price" type="number" step="0.01" value="${x?.price||0}"></div></div><div class="grid g2"><div class="field"><label>Capacity</label><input name="capacity" type="number" min="0" value="${x?.capacity||0}"></div><div class="field"><label>Status</label><select name="status">${['Draft','Published','Sold Out','Closed'].map(z=>`<option ${x?.status===z?'selected':''}>${z}</option>`).join('')}</select></div></div><div class="field"><label>Menu items</label><select multiple name="menu_item_ids" size="6">${m.filter(z=>z.active&&z.available).map(z=>`<option value="${z.id}">${esc(z.name)}</option>`).join('')}</select><div class="muted">Hold Command/Ctrl to select multiple.</div></div><div class="field"><label>Notes</label><textarea name="notes">${esc(x?.notes||'')}</textarea></div><div class="actions"><button type="button" class="btn" onclick="closeModal()">Cancel</button><button class="btn primary">Save</button></div></form>`)}
async function saveBuffet(e,id){e.preventDefault();const f=new FormData(e.target),o={};for(const [k,v] of f.entries()){if(k==='menu_item_ids'){(o.menu_item_ids??=[]).push(Number(v))}else o[k]=v}try{await api(id?'/api/restaurant/buffets/'+id:'/api/restaurant/buffets',{method:id?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(o)});closeModal();restaurantBuffet()}catch(x){toast(x.message)}}
async function deleteBuffet(id){const ok=await confirmAction({title:'Delete Buffet',message:'Delete this buffet configuration?',confirmLabel:'Delete Buffet',tone:'danger',details:[{label:'Buffet',value:'#'+id}]});if(!ok)return;await api('/api/restaurant/buffets/'+id,{method:'DELETE'});restaurantBuffet()}
async function restaurantOpenOrders(tableId){const o=await api('/api/restaurant/orders');const rows=tableId?o.filter(x=>x.table_id==tableId&&x.status==='Open'):o.filter(x=>x.status==='Open');modal(`<h2>MIMI Open Orders</h2><div class="table-wrap"><table class="table"><tr><th>Order</th><th>Table</th><th>Type</th><th>Created</th><th>Status</th><th>Action</th></tr>${rows.map(x=>`<tr><td>${esc(x.order_no)}</td><td>${esc(x.table_name||'—')}</td><td>${esc(x.order_type)}</td><td>${esc(x.created_at)}</td><td><span class="pill warn">Open</span></td><td><button class="btn small primary" onclick="editOpenOrder(${x.id})">Open / Continue</button> <button class="btn small danger" onclick="cancelOpenOrder(${x.id})">Cancel / Delete</button></td></tr>`).join('')}</table></div>${!rows.length?'<p class="muted">No open orders.</p>':''}`)}
async function editOpenOrder(id){const [o,items,p,t]=await Promise.all([api('/api/restaurant/orders'),api('/api/restaurant/orders/'+id+'/items'),api('/api/products'),api('/api/restaurant/tables')]);const order=o.find(x=>x.id==id);if(!order)return;window._rEditItems=items.map(x=>({product_id:x.product_id,name:x.item_name,quantity:x.quantity,unit_price:x.unit_price}));window._rProducts=p.filter(x=>x.business_unit==='MIMI Resturant'&&x.active);modal(`<h2>Open Order · ${esc(order.order_no)}</h2><div class="grid g3"><div class="field"><label>Order type</label><select id="eoType" disabled><option>${esc(order.order_type)}</option></select></div><div class="field"><label>Table</label><select id="eoTable">${t.filter(x=>x.status==='Available'||x.id===order.table_id).map(x=>`<option value="${x.id}" ${x.id===order.table_id?'selected':''}>${esc(x.name)} — ${x.status}</option>`).join('')}</select></div><div class="field"><label>Customer</label><input id="eoCustomer" value="${esc(order.customer_name||'')}"></div></div><div class="menu-grid">${window._rProducts.map(x=>`<button class="menu-item" onclick="addEditRItem(${x.id})"><b>${esc(x.name)}</b><div>${money(x.selling_price)}</div></button>`).join('')}</div><div class="card"><div id="editRCart"></div><div class="actions"><button class="btn" onclick="saveOpenOrder(${id})">Save Changes</button><button class="btn primary" onclick="closeOpenOrder(${id})">Close & Pay</button></div></div>`);drawEditR()}
function addEditRItem(id){const p=window._rProducts.find(x=>x.id==id),x=window._rEditItems.find(x=>x.product_id==id);if(x)x.quantity++;else window._rEditItems.push({product_id:p.id,name:p.name,quantity:1,unit_price:p.selling_price});drawEditR()}
function drawEditR(){const e=document.getElementById('editRCart');if(!e)return;e.innerHTML=window._rEditItems.map((x,i)=>`<div class="cart-row"><span>${esc(x.name)}</span><span><input style="width:60px" type="number" min="0.01" step="0.01" value="${x.quantity}" onchange="window._rEditItems[${i}].quantity=Number(this.value);drawEditR()"> × <input style="width:85px" type="number" step="0.01" value="${x.unit_price}" onchange="window._rEditItems[${i}].unit_price=Number(this.value);drawEditR()"> <b>${money(x.quantity*x.unit_price)}</b> <button class="btn small" onclick="window._rEditItems.splice(${i},1);drawEditR()">Remove</button></span></div>`).join('')||'<span class="muted">No items</span>'}
async function saveOpenOrder(id){try{await api('/api/restaurant/orders/'+id,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({table_id:document.getElementById('eoTable').value,customer_name:document.getElementById('eoCustomer').value,items:window._rEditItems})});toast('Open order saved');editOpenOrder(id)}catch(x){toast(x.message)}}
async function cancelOpenOrder(id){const reason=await reasonAction({title:'Cancel Open Order',message:'The order will be marked Cancelled and retained in history.',confirmLabel:'Cancel Order',tone:'danger',defaultValue:'Customer cancelled',details:[{label:'Order',value:'#'+id}]});if(reason===null)return;try{const d=await api('/api/restaurant/orders/'+id+'/cancel',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({reason:reason.trim()||'Cancelled by user'})});closeModal();toast('Order '+d.order_no+' cancelled');loadView()}catch(x){toast(x.message)}}
async function closeOpenOrder(id){const pay=await choiceAction({title:'Close & Pay Order',message:'Select the payment method before finalizing this order.',label:'Payment Method',options:['Cash','Card','Bank','Credit'],defaultValue:'Cash',confirmLabel:'Close & Pay',details:[{label:'Order',value:'#'+id}]});if(!pay)return;try{await api('/api/restaurant/orders/'+id,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({table_id:document.getElementById('eoTable').value,customer_name:document.getElementById('eoCustomer').value,items:window._rEditItems})});const d=await api('/api/restaurant/orders/'+id+'/close',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({payment_method:pay})});closeModal();toast('Order closed');loadView();if(d.id)printReceipt(d.id)}catch(x){toast(x.message)}}
// Advanced optional feature toggles stored locally for now; UI can hide advanced functions without affecting core POS.
function advancedRestaurantSettings(){modal(`<h2>MIMI Optional Advanced POS Features</h2><div class="grid g2">${['Table Reservations','Table Capacity','Floor/Area Layout','Transfer Order','Merge Tables','Split Bill','Split Payment','Hold/Suspend Order','KOT','Kitchen Display','Waiter Assignment','Table Cleaning','Manager Price Override','Refund Workflow','Cash Drawer/Shift Closing','Delivery Management','Customer Loyalty','Printer Routing'].map((z,i)=>`<label class="field"><span>${z}</span><select id="adv${i}" onchange="localStorage.setItem('mimi_adv_${i}',this.value)"><option value="on" ${localStorage.getItem('mimi_adv_'+i)!=='off'?'selected':''}>ON</option><option value="off" ${localStorage.getItem('mimi_adv_'+i)==='off'?'selected':''}>OFF</option></select></label>`).join('')}</div>`)}


// V11 verified restaurant overrides: these are the active implementations.

async function manageRestaurantTables(){const t=await api('/api/restaurant/tables');modal(`<h2>MIMI · Restaurant Tables</h2><div class="actions" style="justify-content:flex-start"><button class="btn primary" onclick="tableForm();">+ Add Table</button></div><div class="table-wrap" style="margin-top:12px"><table class="table"><tr><th>Table</th><th>Capacity</th><th>Status</th><th>Actions</th></tr>${t.map(x=>`<tr><td>${esc(x.name)}</td><td>${x.capacity}</td><td><span class="pill ${x.status==='Available'?'good':x.status==='Busy'?'bad':'warn'}">${esc(x.status)}</span></td><td><button class="btn small" onclick="tableForm(${x.id})">Edit</button> <button class="btn small danger" onclick="deleteRestaurantTable(${x.id})">Delete Table</button></td></tr>`).join('')}</table></div>`)}
async function deleteRestaurantTable(id){const ok=await confirmAction({title:'Delete Restaurant Table',message:'This is allowed only when the table has no open order.',confirmLabel:'Delete Table',tone:'danger',details:[{label:'Table',value:'#'+id}]});if(!ok)return;try{await api('/api/restaurant/tables/'+id,{method:'DELETE'});toast('Table deleted');manageRestaurantTables();loadView()}catch(x){toast(x.message)}}
async function excavatorAssetForm(id){const [assets,customers]=await Promise.all([api('/api/excavator/assets'),api('/api/crm')]);const x=id?assets.find(z=>z.id==id):null;const cust=customers.filter(z=>z.business_unit==='Excavator');modal(`<h2>${id?'Edit':'Add'} Excavator Equipment / Deal</h2><form onsubmit="saveExcavatorAsset(event,${id||0})"><div class="grid g3"><div class="field"><label>Asset / Deal No.</label><input name="asset_no" value="${esc(x?.asset_no||'EXC-'+new Date().getFullYear()+'-')}" required></div><div class="field"><label>Type</label><select name="type">${['Excavator','Loader','Backhoe','Dozer','Other Equipment'].map(z=>`<option ${x?.type===z?'selected':''}>${z}</option>`).join('')}</select></div><div class="field"><label>Status</label><select name="status">${['Available','Under Repair','In Transit','Reserved','Sold','Cancelled'].map(z=>`<option ${x?.status===z?'selected':''}>${z}</option>`).join('')}</select></div></div><div class="grid g4"><div class="field"><label>Make</label><input name="make" value="${esc(x?.make||'')}"></div><div class="field"><label>Model</label><input name="model" value="${esc(x?.model||'')}"></div><div class="field"><label>Year</label><input name="year" type="number" value="${x?.year||''}"></div><div class="field"><label>Serial / Chassis No.</label><input name="serial_no" value="${esc(x?.serial_no||'')}"></div></div><div class="grid g4"><div class="field"><label>Condition</label><select name="condition_status">${['New','Used','Refurbished','Damaged'].map(z=>`<option ${x?.condition_status===z?'selected':''}>${z}</option>`).join('')}</select></div><div class="field"><label>Purchase Date</label><input name="purchase_date" type="date" value="${x?.purchase_date||''}"></div><div class="field"><label>Buying Price</label><input name="purchase_price" type="number" step="0.01" value="${x?.purchase_price||0}"></div><div class="field"><label>Selling Price</label><input name="selling_price" type="number" step="0.01" value="${x?.selling_price||0}"></div></div><div class="field"><label>Customer</label><select name="customer_id"><option value="">Not assigned</option>${cust.map(z=>`<option value="${z.id}" ${x?.customer_id==z.id?'selected':''}>${esc(z.company)}${z.contact?' — '+esc(z.contact):''}</option>`).join('')}</select></div><div class="field"><label>Notes</label><textarea name="notes">${esc(x?.notes||'')}</textarea></div><div class="actions"><button type="button" class="btn" onclick="closeModal()">Cancel</button><button class="btn primary">Save</button></div></form>`)}
