async function excavatorCosts(id){const [r,l]=await Promise.all([api('/api/excavator/assets/'+id+'/repairs'),api('/api/excavator/assets/'+id+'/logistics')]);modal(`<h2>Excavator Costs & Logistics</h2><div class="grid g2"><div class="card"><div class="section-title"><h3>Repairs</h3><button class="btn small primary" onclick="excavatorRepairForm(${id})">+ Repair</button></div>${r.map(x=>`<div class="row"><span>${esc(x.repair_date||'—')} · ${esc(x.description)}</span><b>${money(x.amount)}</b></div>`).join('')||'<div class="muted">No repairs recorded.</div>'}</div><div class="card"><div class="section-title"><h3>Logistics / Shipping</h3><button class="btn small primary" onclick="excavatorLogisticsForm(${id})">+ Logistics</button></div>${l.map(x=>`<div class="row"><span>${esc(x.mode)} · ${esc(x.origin)} → ${esc(x.destination)}</span><b>${money(x.amount)}</b></div>`).join('')||'<div class="muted">No logistics records.</div>'}</div></div>`)}
