async function restaurantPOS(){const [m,t,b]=await Promise.all([api('/api/restaurant/menu'),api('/api/restaurant/tables'),api('/api/restaurant/buffets')]);const menu=m.filter(x=>x.active&&x.available).map(x=>({id:x.product_id||x.id,product_id:x.product_id||x.id,name:x.name,price:x.price,selling_price:x.price,price_mode:x.price_mode}));const buffets=b.filter(x=>x.status==='Published').map(x=>({id:x.product_id,product_id:x.product_id,name:`${x.name} (Buffet)`,price:Number(x.price||x.selling_price||0),selling_price:Number(x.price||x.selling_price||0),price_mode:'Fixed'}));const products=[...menu,...buffets];window._rItems=[];window._rProducts=products;modal(`<div class="section-title"><h2>MIMI Resturant POS</h2></div><div class="pos-layout"><div><div class="grid g3"><div class="field"><label>Order Type</label><select id="rType" onchange="refreshPosTables()"><option>Dine-in</option><option>Takeaway</option><option>Delivery</option></select></div><div class="field"><label>Table</label><select id="rTable"><option value="">Select available table</option>${t.filter(x=>x.status==='Available').map(x=>`<option value="${x.id}">${esc(x.name)} · ${x.capacity} seats</option>`).join('')}</select></div><div class="field"><label>Customer</label><input id="rCustomer"></div></div><div class="section-title" style="margin-top:14px"><h3>Menu</h3><span class="muted">${menu.length} available</span></div><div class="menu-grid">${menu.map(x=>`<button type="button" class="menu-item" onclick="addRItem(${x.id})"><b>${esc(x.name)}</b><div>${money(x.price)} ${x.price_mode==='Variable'?'· Variable':''}</div></button>`).join('')}</div>${buffets.length?`<div class="section-title" style="margin-top:18px"><h3>Published Buffets</h3><span class="muted">${buffets.length} available</span></div><div class="menu-grid">${buffets.map(x=>`<button type="button" class="menu-item" onclick="addRItem(${x.product_id})"><b>🍽️ ${esc(x.name)}</b><div>${money(x.price)} · Published</div></button>`).join('')}</div>`:''}</div><div class="card"><h3>Order</h3><div id="rCart"></div><div class="field"><label>Payment Method</label><select id="rPayment"><option>Cash</option><option>Card</option><option>Bank</option><option>Credit</option></select></div><div class="actions"><button type="button" class="btn" onclick="closeModal()">Cancel</button><button type="button" class="btn" onclick="saveROrderOpen()">Save Open Order</button><button class="btn primary" onclick="saveROrder()">Close & Pay</button></div></div></div>`);drawR()}
async function refreshPosTables(){const t=await api('/api/restaurant/tables');const type=document.getElementById('rType').value;document.getElementById('rTable').innerHTML=type==='Dine-in'?`<option value="">Select available table</option>${t.filter(x=>x.status==='Available').map(x=>`<option value="${x.id}">${esc(x.name)} · ${x.capacity} seats</option>`).join('')}`:'<option value="">No table</option>'}
function addRItem(id){const p=window._rProducts.find(x=>x.id==id||x.product_id==id);if(!p)return toast('Item unavailable');const pid=p.product_id||p.id,x=window._rItems.find(x=>x.product_id==pid);if(x)x.quantity++;else window._rItems.push({product_id:pid,name:p.name,quantity:1,unit_price:Number(p.price??p.selling_price??0)});drawR()}
function drawR(){const e=document.getElementById('rCart');if(!e)return;e.innerHTML=window._rItems.map((x,i)=>`<div class="cart-row"><span>${esc(x.name)}</span><span><input type="number" min="0.01" step="0.01" value="${x.quantity}" style="width:60px" onchange="window._rItems[${i}].quantity=Number(this.value);drawR()"> × <input type="number" min="0" step="0.01" value="${x.unit_price}" style="width:85px" onchange="window._rItems[${i}].unit_price=Number(this.value);drawR()"> <b>${money(x.quantity*x.unit_price)}</b> <button class="btn small" onclick="window._rItems.splice(${i},1);drawR()">Remove</button></span></div>`).join('')||'<span class="muted">No items</span>'}
async function saveROrderOpen(){if(!window._rItems.length)return toast('Add menu items');try{const type=document.getElementById('rType').value,table=document.getElementById('rTable').value;if(type==='Dine-in'&&!table)return toast('Select an available table');const d=await api('/api/restaurant/orders',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({table_id:table||null,order_type:type,customer_name:document.getElementById('rCustomer').value,items:window._rItems})});await api('/api/restaurant/orders/'+d.id+'/save',{method:'POST'});closeModal();toast(`Open order ${d.order_no} saved`);loadView()}catch(x){toast(x.message)}}
async function saveROrder(){if(!window._rItems.length)return toast('Add menu items');try{const type=document.getElementById('rType').value,table=document.getElementById('rTable').value;if(type==='Dine-in'&&!table)return toast('Select an available table');const d=await api('/api/restaurant/orders',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({table_id:table||null,order_type:type,customer_name:document.getElementById('rCustomer').value,items:window._rItems})});const sale=await api('/api/restaurant/orders/'+d.id+'/close',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({payment_method:document.getElementById('rPayment').value})});if(sale.approval_required){toast(sale.message||'Sale submitted for approval. The restaurant order remains open.');loadView();return;}closeModal();toast('Order closed and posted');loadView();if(sale.id)printReceipt(sale.id)}catch(x){toast(x.message)}}
async function menuItemStockForm(menuId){const m=await api('/api/restaurant/menu');const x=m.find(z=>z.id==menuId);if(!x)return toast('Menu item not found');modal(`<h2>Update Stock · ${esc(x.name)}</h2><p class="muted">Updates the inventory item linked to this menu item.</p><form onsubmit="saveMenuItemStock(event,${menuId})"><div class="field"><label>Movement</label><select name="type"><option value="RECEIVE">Receive / Add</option><option value="ADJUST">Adjustment / Add</option><option value="ISSUE">Issue / Remove</option><option value="WASTE">Waste / Remove</option></select></div><div class="field"><label>Quantity</label><input name="quantity" type="number" step="0.01" min="0.01" required></div><div class="field"><label>Reason</label><select name="reason"><option>Purchase</option><option>Opening Stock</option><option>Physical Count</option><option>Waste</option><option>Damaged</option><option>Internal Use</option><option>Other</option></select></div><div class="actions"><button type="button" class="btn" onclick="closeModal()">Cancel</button><button class="btn primary">Update Stock</button></div></form>`)}
async function saveMenuItemStock(e,id){e.preventDefault();try{await api('/api/restaurant/menu/'+id+'/stock',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});closeModal();restaurantMenu()}catch(x){toast(x.message)}}
async function recipeForm(id){const [m,p,r]=await Promise.all([api('/api/restaurant/menu'),api('/api/products'),api('/api/restaurant/menu/'+id+'/recipe')]);const x=m.find(z=>z.id==id);const ingredients=p.filter(z=>z.business_unit==='MIMI Resturant'&&z.item_type==='PRODUCT'&&z.active);modal(`<h2>Ingredients / Recipe · ${esc(x.name)}</h2><form onsubmit="saveRecipe(event,${id})"><div class="grid g3"><div class="field"><label>Ingredient</label><select name="product_id">${ingredients.map(z=>`<option value="${z.id}">${esc(z.name)}</option>`).join('')}</select></div><div class="field"><label>Quantity per serving</label><input name="quantity" type="number" step="0.001" min="0.001" required></div><div class="field"><label>Unit</label><select name="unit"><option>pcs</option><option>kg</option><option>g</option><option>litre</option><option>ml</option><option>plate</option></select></div></div><button class="btn primary">Add / Update Ingredient</button></form><div class="table-wrap" style="margin-top:14px"><table class="table"><tr><th>Ingredient</th><th>Qty</th><th>Unit</th><th>Stock</th><th>Action</th></tr>${r.map(z=>`<tr><td>${esc(z.product_name)}</td><td>${z.quantity}</td><td>${esc(z.unit)}</td><td>${z.current_stock}</td><td><button class="btn small danger" onclick="deleteRecipe(${id},${z.id})">Remove</button></td></tr>`).join('')}</table></div>`)}
