async function weeklyForm(id){const [w,m]=await Promise.all([api('/api/restaurant/weekly-menu'),api('/api/restaurant/menu')]);const x=id?w.find(z=>z.id==id):null;modal(`<h2>${id?'Edit':'Add'} Weekly Menu</h2><form onsubmit="saveWeekly(event,${id||0})"><div class="grid g3"><div class="field"><label>Date</label><input name="menu_date" type="date" value="${x?.menu_date||''}" required></div><div class="field"><label>Meal period</label><select name="meal_period">${['All Day','Breakfast','Lunch','Dinner'].map(z=>`<option ${x?.meal_period===z?'selected':''}>${z}</option>`).join('')}</select></div><div class="field"><label>Menu item</label><select name="menu_item_id">${m.filter(z=>z.active&&z.available).map(z=>`<option value="${z.id}" ${x?.menu_item_id==z.id?'selected':''}>${esc(z.name)}</option>`).join('')}</select></div></div><div class="field"><label>Published</label><select name="published"><option value="1" ${x?.published?'selected':''}>Publish</option><option value="0" ${x&&!x.published?'selected':''}>Draft</option></select></div><div class="field"><label>Notes</label><textarea name="notes">${esc(x?.notes||'')}</textarea></div><div class="actions"><button type="button" class="btn" onclick="closeModal()">Cancel</button><button class="btn primary">Save</button></div></form>`)}
async function saveWeekly(e,id){e.preventDefault();try{const o=Object.fromEntries(new FormData(e.target));await api(id?'/api/restaurant/weekly-menu/'+id:'/api/restaurant/weekly-menu',{method:id?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(o)});closeModal();restaurantWeekly()}catch(x){toast(x.message)}}
async function editOpenOrder(id){const [o,t,m]=await Promise.all([api('/api/restaurant/orders/'+id),api('/api/restaurant/tables'),api('/api/restaurant/menu')]);if(o.status!=='Open')return toast('Only open orders can be edited');window._rEditItems=o.items.map(x=>({product_id:x.product_id,name:x.item_name,quantity:x.quantity,unit_price:x.unit_price,notes:x.notes||''}));window._rEditProducts=m.filter(x=>x.active&&x.available);modal(`<h2>Open Order · ${esc(o.order_no)}</h2><div class="grid g3"><div class="field"><label>Order Type</label><select id="erType"><option ${o.order_type==='Dine-in'?'selected':''}>Dine-in</option><option ${o.order_type==='Takeaway'?'selected':''}>Takeaway</option><option ${o.order_type==='Delivery'?'selected':''}>Delivery</option></select></div><div class="field"><label>Table</label><select id="erTable"><option value="">No table</option>${t.filter(x=>x.status==='Available'||x.id===o.table_id).map(x=>`<option value="${x.id}" ${x.id===o.table_id?'selected':''}>${esc(x.name)} · ${x.status}</option>`).join('')}</select></div><div class="field"><label>Customer</label><input id="erCustomer" value="${esc(o.customer_name||'')}"></div></div><div class="menu-grid">${window._rEditProducts.map(x=>`<button type="button" class="menu-item" onclick="addEditRItem(${x.id})"><b>${esc(x.name)}</b><div>${money(x.price)} ${x.price_mode==='Variable'?'· Variable':''}</div></button>`).join('')}</div><div class="card"><h3>Order Items</h3><div id="erCart"></div></div><div class="actions"><button type="button" class="btn danger" onclick="cancelOpenOrder(${id})">Cancel / Delete</button><button type="button" class="btn" onclick="closeModal()">Keep Open</button><button type="button" class="btn primary" onclick="saveOpenOrder(${id})">Save Changes</button><button type="button" class="btn primary" onclick="closeOpenOrder(${id})">Close & Pay</button></div>`);drawEditR()}
function addEditRItem(id){const p=window._rEditProducts.find(x=>x.id==id),x=window._rEditItems.find(x=>x.product_id==p.product_id);if(x)x.quantity++;else window._rEditItems.push({product_id:p.product_id,name:p.name,quantity:1,unit_price:p.price});drawEditR()}
function drawEditR(){const e=document.getElementById('erCart');if(!e)return;e.innerHTML=window._rEditItems.map((x,i)=>`<div class="cart-row"><span>${esc(x.name)}</span><span><input type="number" min="0.01" step="0.01" value="${x.quantity}" style="width:60px" onchange="window._rEditItems[${i}].quantity=Number(this.value);drawEditR()"> × <input type="number" min="0" step="0.01" value="${x.unit_price}" style="width:85px" onchange="window._rEditItems[${i}].unit_price=Number(this.value);drawEditR()"> <b>${money(x.quantity*x.unit_price)}</b> <button class="btn small" onclick="window._rEditItems.splice(${i},1);drawEditR()">Remove</button></span></div>`).join('')||'<span class="muted">No items</span>'}
async function saveOpenOrder(id){try{if(!window._rEditItems.length)return toast('An open order must contain at least one item');await api('/api/restaurant/orders/'+id,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({order_type:document.getElementById('erType').value,table_id:document.getElementById('erTable').value||null,customer_name:document.getElementById('erCustomer').value,items:window._rEditItems})});await api('/api/restaurant/orders/'+id+'/save',{method:'POST'});closeModal();toast('Open order saved');loadView()}catch(x){toast(x.message)}}
async function closeOpenOrder(id){const pay=await choiceAction({title:'Close & Pay Order',message:'Select the payment method before finalizing this order.',label:'Payment Method',options:['Cash','Card','Bank','Credit'],defaultValue:'Cash',confirmLabel:'Close & Pay',details:[{label:'Order',value:'#'+id}]});if(pay===null)return;try{await api('/api/restaurant/orders/'+id,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({order_type:document.getElementById('erType').value,table_id:document.getElementById('erTable').value||null,customer_name:document.getElementById('erCustomer').value,items:window._rEditItems})});const d=await api('/api/restaurant/orders/'+id+'/close',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({payment_method:pay})});if(d.approval_required)return toast(d.message||'Sale submitted for approval. The order remains open.');closeModal();toast('Order closed and posted');loadView();if(d.id)printReceipt(d.id)}catch(x){toast(x.message)}}

boot();


