// V27.5: no timer/focus polling. Views refresh only after explicit navigation or successful mutations.

// V28.0 shared UI safeguards and workflow enhancements.
function enhanceMandatoryEvidenceFields(){
  const forms=[...document.querySelectorAll('#modalRoot form')];
  for(const form of forms){const submit=form.getAttribute('onsubmit')||'',actions=form.querySelector('.actions');if(!actions)continue;
    const add=(name,label,required=true,multiple=false)=>{if(form.querySelector(`[name="${name}"]`))return;actions.insertAdjacentHTML('beforebegin',`<div class="field v280-evidence"><label>${esc(t(label))}${required?' *':''}</label><input name="${name}" type="file" accept="application/pdf,image/*" ${multiple?'multiple':''} ${required?'required':''}><small class="muted">${esc(t('This record cannot be saved without receipt or supporting evidence.'))}</small></div>`)};
    if(submit.includes('saveSimpleExcavatorMachine'))add('payment_evidence','Purchase Token Receipt / Evidence',false,true);
    if(submit.includes('completeExcavatorSale'))add('payment_evidence','Sale Payment Receipt / Evidence',true,true);
    if(submit.includes('saveExcavatorRepair'))add('evidence','Repair Payment Receipt / Evidence',true);
    if(submit.includes('saveExcavatorLogistics'))add('evidence','Logistics Payment Receipt / Evidence',true);
    if(submit.includes('saveSimpleExcavatorCost')){const input=form.querySelector('[name="files"]');if(input){input.required=true;input.closest('.field')?.querySelector('label')?.replaceChildren(document.createTextNode(t('Receipt / Evidence *')))}}
    if(submit.includes('saveExcavatorPayment')){const input=form.querySelector('[name="receipt"]');if(input){input.required=true;input.closest('.field')?.querySelector('label')?.replaceChildren(document.createTextNode(t('Payment Receipt / Evidence *')))}}
  }
}
function enhanceBuyerRequirementActions(){document.querySelectorAll('#modalRoot button[onclick^="deleteExcavatorBuyerRequirement("]').forEach(btn=>{if(btn.dataset.enhanced)return;const m=(btn.getAttribute('onclick')||'').match(/\((\d+),(\d+)\)/);if(!m)return;btn.dataset.enhanced='1';btn.insertAdjacentHTML('beforebegin',`<button class="btn small" onclick="excavatorBuyerRequirementView(${m[1]},${m[2]})">${esc(t('View'))}</button> <button class="btn small" onclick="excavatorBuyerRequirementForm(${m[1]},${m[2]})">${esc(t('Edit'))}</button> <button class="btn small primary" onclick="excavatorBuyerRequirementMatches(${m[1]},${m[2]})">${esc(t('Matches'))}</button> `)})}

async function saveSimpleExcavatorMachine(e){e.preventDefault();const form=e.target,btn=form.querySelector('button[type="submit"]');if(!form.reportValidity())return;try{const fd=new FormData(form),tokenAmount=Number(fd.get('purchase_token')||0);if(!fd.get('asset_no')||!fd.get('machine_name')||!fd.get('make')||!fd.get('model')||!fd.get('purchase_date')||Number(fd.get('purchase_price'))<=0)throw new Error('Please complete Deal No., Machine Name, Make, Model, Purchase Date and Purchase Price.');if(tokenAmount>0&&!form.querySelector('[name="payment_evidence"]')?.files.length)throw new Error('Receipt / evidence is mandatory for the purchase token payment.');if(tokenAmount>0&&!String(fd.get('token_payment_reference')||'').trim())throw new Error('Token payment reference is required.');if(btn){btn.disabled=true;btn.textContent=tr('common.saving')}const result=await multipartApi('/api/excavator/assets',fd);if(result.approval_required){if(btn){btn.disabled=false;btn.textContent=t('Save Machine')}return toast(result.message||'Machine purchase submitted for approval')}closeModalAfterSave();toast(result.new_supplier?'Machine saved · New supplier added':result.requirement_matches?`Machine saved · ${result.requirement_matches} supplier requirement match(es) found`:'Machine saved successfully');loadView()}catch(x){if(btn){btn.disabled=false;btn.textContent=t('Save Machine')}toast(x.message)}}
async function saveSimpleExcavatorCost(e,id){e.preventDefault();const form=e.target;if(!form.reportValidity())return;try{const fd=new FormData(form);fd.set('stage','Costs');fd.set('currency','KRW');fd.set('status','Open');fd.set('include_in_machine_cost',fd.get('include_cost')==='1'?'1':'0');const r=await multipartApi('/api/excavator/assets/'+id+'/transactions',fd);closeModalAfterSave();toast('Cost added'+(r.document_count?` with ${r.document_count} attachment(s)`:'') );excavatorOpenMachine(id)}catch(x){toast(x.message)}}
async function completeExcavatorSale(e,id){e.preventDefault();const form=e.target;if(!form.reportValidity())return;const submit=form.querySelector('[type="submit"]'),original=submit?.textContent;if(submit){submit.disabled=true;submit.textContent=form.sale_update?.value==='1'?tr('common.updating'):tr('common.completing')}try{const fd=new FormData(form);for(const [k,v] of [...fd.entries()])if(typeof v==='string')fd.set(k,v.trim());const saleType=String(fd.get('sale_type')||''),destination=saleType==='Export Sale'?(fd.get('destination_country')==='__OTHER__'?fd.get('other_destination_country'):fd.get('destination_country')):'';fd.set('destination_country',String(destination||''));if(!fd.get('customer_name'))throw new Error('Customer / Buyer is required.');if(!(Number(fd.get('selling_price'))>0))throw new Error('Selling Price must be greater than zero.');if(!fd.get('buyer_id')){fd.set('new_buyer_name',fd.get('new_buyer_name')||fd.get('customer_name'));fd.set('new_buyer_country',fd.get('new_buyer_country')||destination);if(!fd.get('new_buyer_name')||!fd.get('new_buyer_country'))throw new Error('Complete new buyer name and country are required.')}if(!form.querySelector('[name="payment_evidence"]')?.files.length)throw new Error('Receipt / evidence is mandatory for the sale payment.');const r=await multipartApi('/api/excavator/assets/'+id+'/complete-sale',fd);if(r.approval_required){if(submit){submit.disabled=false;submit.textContent=original}return toast(r.message||'Approval is required before this sale change can be applied.')}closeModalAfterSave();toast(r.updated?'Sale updated · Finance synchronized · Sale PDF updated':'Sale completed · Buyer and Finance synchronized · Sale PDF created');loadView();if(r.document_url)setTimeout(()=>window.open(r.document_url,'_blank'),250)}catch(x){if(submit){submit.disabled=false;submit.textContent=original}toast(x.message)}}
async function saveExcavatorPayment(e,id){e.preventDefault();const form=e.target;if(!form.reportValidity())return;try{const fd=new FormData(form);if(!fd.get('payment_date'))throw new Error('Payment Date is required.');if(!String(fd.get('reference')||'').trim())throw new Error('Reference is required.');if(!form.querySelector('[name="receipt"]')?.files.length)throw new Error('Receipt / evidence is mandatory for every Excavator payment.');const j=await multipartApi('/api/excavator/assets/'+id+'/payments',fd);toast(j.receipt_document_id?'Payment saved and receipt added to Documents':'Payment saved');scheduleDataSync();excavatorPayments(id)}catch(x){toast(x.message)}}
async function uploadExcavatorDocuments(e,id){e.preventDefault();const form=e.target;if(!form.reportValidity())return;try{const j=await multipartApi('/api/excavator/assets/'+id+'/documents',new FormData(form));toast(j.count+' document(s) uploaded');scheduleDataSync();excavatorDocuments(id)}catch(x){toast(x.message)}}
async function saveExcavatorRepair(e,id){e.preventDefault();if(!e.target.reportValidity())return;try{await multipartApi('/api/excavator/assets/'+id+'/repairs',new FormData(e.target));markFormSaved();excavatorCosts(id)}catch(x){toast(x.message)}}
async function saveExcavatorLogistics(e,id){e.preventDefault();if(!e.target.reportValidity())return;try{await multipartApi('/api/excavator/assets/'+id+'/logistics',new FormData(e.target));markFormSaved();excavatorCosts(id)}catch(x){toast(x.message)}}
async function saveExcavatorBuyerResale(e,id,rid){e.preventDefault();const form=e.target;if(!form.reportValidity())return;try{const fd=new FormData(form),received=Number(fd.get('amount_received_pkr')||0);if(received>0&&!rid&&!form.querySelector('[name="receipt"]')?.files.length)throw new Error('Receipt / evidence is mandatory when resale-profit payment is received.');if(rid)fd.delete('asset_id');await multipartApi('/api/excavator/buyers/'+id+'/resale-shares'+(rid?'/'+rid:''),fd,{method:rid?'PUT':'POST'});closeModalAfterSave();toast(rid?'Resale record updated':'Resale profit-share record saved');excavatorBuyerDetail(id)}catch(x){toast(x.message)}}

async function excavatorBuyerRequirementForm(id,rid=0){const x=rid?await api(`/api/excavator/buyers/${id}/requirements/${rid}`):{};modal(`<h2>${rid?'Edit':'Add'} Buyer Requirement</h2><p class="muted">Use the same structured machine data used for supplier listings. Matching available supplier machines will be shown automatically.</p><form onsubmit="saveExcavatorBuyerRequirement(event,${id},${rid})"><div class="field"><label>Requirement / Purpose *</label><textarea name="requirement" required>${esc(x.requirement||'')}</textarea></div><div class="grid g3"><div class="field"><label>Machine Name</label><input name="machine_name" value="${esc(x.machine_name||'')}"></div><div class="field"><label>Machine Type</label><select name="machine_type"><option value="">Any</option>${['Excavator','Loader','Backhoe','Dozer','Other Equipment'].map(v=>`<option ${x.machine_type===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label>Condition</label><select name="condition_status"><option value="">Any</option>${['New','Used','Refurbished','Damaged'].map(v=>`<option ${x.condition_status===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label>Make</label><input name="make" value="${esc(x.make||'')}"></div><div class="field"><label>Model</label><input name="model" value="${esc(x.model||'')}"></div><div class="field"><label>Serial / Chassis No.</label><input name="serial_no" value="${esc(x.serial_no||'')}"></div><div class="field"><label>Min Year</label><input name="min_year" type="number" value="${x.min_year||''}"></div><div class="field"><label>Max Year</label><input name="max_year" type="number" value="${x.max_year||''}"></div><div class="field"><label>Location</label><input name="location" value="${esc(x.location||'')}"></div><div class="field"><label>Budget Max (KRW)</label><input name="budget_max" type="number" min="0" value="${x.budget_max||''}"></div><div class="field"><label>Quantity</label><input name="quantity" type="number" min="1" value="${x.quantity||1}"></div><div class="field"><label>Status</label><select name="status">${['Active','On Hold','Fulfilled','Cancelled'].map(v=>`<option ${x.status===v?'selected':''}>${v}</option>`).join('')}</select></div></div><div class="field"><label>Notes</label><textarea name="notes">${esc(x.notes||'')}</textarea></div><div class="actions"><button type="button" class="btn" onclick="closeModal();excavatorBuyerDetail(${id})">Cancel</button><button class="btn primary">${rid?'Update Requirement':'Save Requirement'}</button></div></form>`)}
async function saveExcavatorBuyerRequirement(e,id,rid=0){e.preventDefault();try{const o=Object.fromEntries(new FormData(e.target)),r=await api(`/api/excavator/buyers/${id}/requirements${rid?'/'+rid:''}`,{method:rid?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(o)});closeModalAfterSave();toast(`Buyer requirement saved · ${r.match_count||0} supplier match(es)`);excavatorBuyerDetail(id)}catch(x){toast(x.message)}}
async function excavatorBuyerRequirementView(id,rid){const x=await api(`/api/excavator/buyers/${id}/requirements/${rid}`);modal(`<div class="section-title"><div><h2>Buyer Requirement</h2><div class="muted">${esc(x.requirement||'')}</div></div><span class="pill ${x.status==='Active'?'good':'warn'}">${esc(x.status)}</span></div><div class="grid g3"><div class="card"><small>Machine</small><b>${esc(x.machine_name||'Any')} · ${esc(x.machine_type||'Any')}</b></div><div class="card"><small>Make / Model</small><b>${esc(x.make||'Any')} · ${esc(x.model||'Any')}</b></div><div class="card"><small>Year</small><b>${esc(x.min_year||'Any')} – ${esc(x.max_year||'Any')}</b></div><div class="card"><small>Condition</small><b>${esc(x.condition_status||'Any')}</b></div><div class="card"><small>Serial / Chassis</small><b>${esc(x.serial_no||'Any')}</b></div><div class="card"><small>Location</small><b>${esc(x.location||'Any')}</b></div><div class="card"><small>Budget</small><b>₩ ${money(x.budget_max||0)}</b></div><div class="card"><small>Quantity</small><b>${money(x.quantity||1)}</b></div><div class="card"><small>Supplier Matches</small><b>${x.match_count||0}</b></div></div><div class="card" style="margin-top:12px"><b>Notes</b><p>${esc(x.notes||'—')}</p></div><div class="actions"><button class="btn" onclick="excavatorBuyerRequirementForm(${id},${rid})">Edit</button><button class="btn primary" onclick="excavatorBuyerRequirementMatches(${id},${rid})">View Matches</button><button class="btn" onclick="closeModal();excavatorBuyerDetail(${id})">Close</button></div>`)}
async function excavatorBuyerRequirementMatches(id,rid){const d=await api(`/api/excavator/buyers/${id}/requirements/${rid}/matches`);modal(`<h2>Matching Supplier Machines</h2><p class="muted">Matches use the structured requirement fields and currently available supplier listings.</p>${d.matches.map(x=>`<div class="card" style="margin-bottom:10px"><div class="section-title"><div><b>${esc(x.machine_name||x.make+' '+x.model)}</b><div class="muted">${esc(x.supplier_name)} · ${esc(x.location||'')}</div></div><span class="pill good">${esc(x.status)}</span></div><div class="grid g4"><div><small>Type</small><b>${esc(x.machine_type||'')}</b></div><div><small>Make / Model</small><b>${esc(x.make)} ${esc(x.model)}</b></div><div><small>Year / Condition</small><b>${esc(x.year||'—')} · ${esc(x.condition_status||'')}</b></div><div><small>Asking Price</small><b>₩ ${money(x.asking_price)}</b></div></div><div class="muted">${esc(x.serial_no||'')} · ${esc(x.supplier_phone||'')} · ${esc(x.supplier_email||'')}</div></div>`).join('')||'<div class="empty">No available supplier machines match this requirement.</div>'}<div class="actions"><button class="btn" onclick="excavatorBuyerRequirementView(${id},${rid})">Back</button><button class="btn primary" onclick="closeModal();go('excavatorSuppliers')">Open Suppliers</button></div>`)}

async function financeCorrectionOpen(id){const x=(window._financeCorrections||[]).find(r=>Number(r.id)===Number(id));if(!x)return toast('Correction request not found');try{await api('/api/finance/corrections/'+id+'/view',{method:'POST'});modal(`<div class="section-title"><div><h2>Finance Correction Request</h2><div class="muted">Finance #${x.finance_entry_id} · ${esc(x.business_unit||'')}</div></div><span class="pill warn">${esc(x.status)}</span></div><div class="grid g3"><div class="card"><small>Assigned User</small><b>${esc(x.assigned_to_name||'')}</b></div><div class="card"><small>Requested By</small><b>${esc(x.requested_by_name||'')}</b></div><div class="card"><small>Due</small><b>${esc(x.due_at||'—')}</b></div></div><div class="card" style="margin-top:12px"><h3>Reason / Requested Changes</h3><p>${esc(x.reason)}</p><p class="muted">${esc(x.requested_changes||'')}</p></div><div class="card" style="margin-top:12px"><h3>Original Finance Record</h3><div>${esc(x.finance_type)} · ${esc(x.category)} · ₩ ${money(x.amount)}</div><div class="muted">${esc(x.description||'')} · ${esc(x.reference||'')}</div></div>${x.response_note?`<div class="card" style="margin-top:12px"><h3>Response</h3><p>${esc(x.response_note)}</p></div>`:''}<div class="actions"><button class="btn" onclick="closeModal()">Close</button>${['Open','Viewed'].includes(x.status)?`<button class="btn primary" onclick="financeCorrectionRespond(${id})">Correct & Resubmit</button>`:''}<button class="btn" onclick="closeModal(true);financeOpen(${x.finance_entry_id})">Open Finance Record</button></div>`)}catch(e){toast(e.message)}}
async function financeCorrectionRespond(id){const x=(window._financeCorrections||[]).find(r=>Number(r.id)===Number(id));if(!x)return toast('Correction request not found');await api('/api/finance/corrections/'+id+'/view',{method:'POST'});closeModal(true);financeEdit(x.finance_entry_id,id)}
async function financeEdit(id,correctionId=0){const rows=await api('/api/finance'),x=rows.find(z=>z.id==id),correction=(window._financeCorrections||[]).find(z=>Number(z.id)===Number(correctionId)||Number(z.finance_entry_id)===Number(id)&&['Open','Viewed'].includes(z.status));if(!x)return;modal(`<h2>${correction?'Correct & Resubmit':'Edit'} Finance Entry</h2>${correction?`<div class="review-warning critical"><b>Correction requested</b><span>${esc(correction.reason)} · ${esc(correction.requested_changes||'')}</span></div>`:''}<form onsubmit="saveFinanceEdit(event,${id})" enctype="multipart/form-data"><div class="grid g2"><div class="field"><label>Type</label><select name="type"><option ${x.type==='Expense'?'selected':''}>Expense</option><option ${x.type==='Revenue'?'selected':''}>Revenue</option></select></div><div class="field"><label>Amount</label><input name="amount" type="number" min="0.01" step="0.01" value="${x.amount}" required></div></div><div class="grid g2"><div class="field"><label>Category</label><input name="category" value="${esc(x.category||'')}" required></div><div class="field"><label>Payment</label><select name="payment_method">${['Cash','Card','Bank','Credit','Other'].map(v=>`<option ${x.payment_method===v?'selected':''}>${v}</option>`).join('')}</select></div></div><div class="field"><label>Description</label><textarea name="description">${esc(x.description||'')}</textarea></div><div class="field"><label>Reference</label><input name="reference" value="${esc(x.reference||'')}"></div>${correction?`<div class="field"><label>Correction Response *</label><textarea name="response_note" required placeholder="Explain exactly what was corrected">${esc(correction.response_note||'')}</textarea></div><div class="field"><label>Receipt / Correction Evidence ${x.receipt_file?'':'*'}</label><input name="attachments" type="file" multiple accept="application/pdf,image/*" ${x.receipt_file?'':'required'}><small class="muted">Upload revised receipt or evidence when required.</small></div>`:''}<div class="actions"><button type="button" class="btn" onclick="closeModal()">Cancel</button><button class="btn primary">${correction?'Save & Resubmit':'Update'}</button></div></form>`)}
async function saveFinanceEdit(e,id){e.preventDefault();const form=e.target;if(!form.reportValidity())return;const fd=new FormData(form),ok=await confirmAction({title:'Save Finance Correction',message:'This updates the existing Finance record and returns it to the verification queue as Resubmitted. It does not create a duplicate transaction.',confirmLabel:'Save & Resubmit',details:[{label:'Finance Record',value:'#'+id},{label:'Type',value:fd.get('type')||''},{label:'Amount',value:'₩ '+money(fd.get('amount')||0)},{label:'Category',value:fd.get('category')||''}]});if(!ok)return;try{await multipartApi('/api/finance/'+id,fd,{method:'PUT'});closeModalAfterSave();toast('Finance corrected and resubmitted');loadView()}catch(x){toast(x.message)}}
function enhancePerformanceFinanceMetrics(){if(view!=='performance'||document.getElementById('financeCorrectionPerformance'))return;const people=window._performancePeople||[],grid=document.querySelector('#content .grid.g3');if(!grid)return;const total=people.reduce((n,p)=>n+Number(p.performance.finance_corrections?.total||0),0),open=people.reduce((n,p)=>n+Number(p.performance.finance_corrections?.open||0),0),overdue=people.reduce((n,p)=>n+Number(p.performance.finance_corrections?.overdue||0),0);const section=document.createElement('div');section.id='financeCorrectionPerformance';section.className='card';section.style.marginTop='16px';section.innerHTML=`<div class="section-title"><div><h3>${esc(t('Finance Correction Performance'))}</h3><div class="muted">${esc(t('Fairness-focused metrics: assigned requests, response time, overdue work and resubmissions.'))}</div></div></div><div class="grid g3"><div class="card stat"><div class="label">${esc(t('Correction Requests'))}</div><div class="value">${total}</div></div><div class="card stat"><div class="label">${esc(t('Open'))}</div><div class="value">${open}</div></div><div class="card stat"><div class="label">${esc(t('Overdue'))}</div><div class="value">${overdue}</div></div></div><div class="table-wrap" style="margin-top:12px"><table class="table"><tr><th>${esc(t('Employee'))}</th><th>${esc(t('Total'))}</th><th>${esc(t('Open'))}</th><th>${esc(t('Overdue'))}</th><th>${esc(t('Responded'))}</th><th>${esc(t('Resubmissions'))}</th><th>${esc(t('Average Response'))}</th></tr>${people.map(p=>{const f=p.performance.finance_corrections||{};return `<tr><td><b>${esc(p.name)}</b><div class="muted">${esc(p.role)}</div></td><td>${f.total||0}</td><td>${f.open||0}</td><td>${f.overdue||0}</td><td>${f.responded||0}</td><td>${f.resubmissions||0}</td><td>${Number(f.avg_response_hours||0).toFixed(1)} h</td></tr>`}).join('')}</table></div>`;grid.insertAdjacentElement('afterend',section);translateElement(section)}
const v280PerformanceObserver=new MutationObserver(()=>enhancePerformanceFinanceMetrics());v280PerformanceObserver.observe(root,{childList:true,subtree:true});

