function financeCanCreateManual(){return !!me&&['CEO / Owner','Operations Manager','Finance / Admin','Business Unit Manager'].includes(me.role)}
function allowed(key){
  if(!me)return false;
  if(key==='businesses')return me.role==='CEO / Owner'&&!selectedUnitId;
  if(me.role==='CEO / Owner')return true;
  const map={dashboard:1,finance:1,sales:['Operations Manager','Finance / Admin','Sales / Business Development','Business Unit Manager'],purchases:['Operations Manager','Finance / Admin','Business Unit Manager'],inventory:['Operations Manager','Finance / Admin','Business Unit Manager','Staff Member'],approvals:['Operations Manager','Finance / Admin','Sales / Business Development','Business Unit Manager'],tasks:1,performance:['Operations Manager','Finance / Admin','Sales / Business Development','Business Unit Manager','Staff Member'],reports:['Operations Manager','Finance / Admin','Sales / Business Development','Business Unit Manager','Staff Member'],documents:['Operations Manager','Finance / Admin','Sales / Business Development','Business Unit Manager','Staff Member'],meetings:1,restaurant:['Operations Manager','Business Unit Manager'],excavator:['Operations Manager','Finance / Admin','Sales / Business Development','Business Unit Manager'],excavatorSuppliers:['Operations Manager','Finance / Admin','Sales / Business Development','Business Unit Manager'],excavatorBuyers:['Operations Manager','Finance / Admin','Sales / Business Development','Business Unit Manager'],users:['Operations Manager'],audit:['Operations Manager']};
  return map[key]===1||map[key]?.includes(me.role)||['notifications','profile'].includes(key);
}
function navButton(x){
  const count=Number(actionCounts[x[0]]||0),badge=count>0?`<span class="nav-action-badge" data-nav-badge>${count>99?'99+':count}</span>`:'';
  return `<button data-nav-key="${esc(x[0])}" class="${view===x[0]?'active':''}" title="${esc(t(x[1]))}" aria-current="${view===x[0]?'page':'false'}" onclick="closeMobileSidebar();go('${x[0]}')"><span class="nav-icon">${x[2]||'•'}</span><span class="nav-label">${esc(t(x[1]))}</span>${badge}</button>`;
}
async function refreshActionCounts(){
  if(!me)return;
  try{
    const result=await api('/api/action-counts');actionCounts=result.counts||{};
    document.querySelectorAll('[data-nav-key]').forEach(button=>{
      const count=Number(actionCounts[button.dataset.navKey]||0),existing=button.querySelector('[data-nav-badge]');
      if(count>0){if(existing)existing.textContent=count>99?'99+':count;else button.insertAdjacentHTML('beforeend',`<span class="nav-action-badge" data-nav-badge>${count>99?'99+':count}</span>`)}else existing?.remove();
    });
  }catch(e){console.warn('Action counters:',e.message)}
}
function ensureActiveNavVisible(){setTimeout(()=>document.querySelector('.nav button.active')?.scrollIntoView({block:'nearest',inline:'nearest'}),20)}
function captureViewState(){
  const c=document.getElementById('content');if(!c)return;const fields={};
  c.querySelectorAll('input[id],select[id],textarea[id],input[name],select[name],textarea[name]').forEach(el=>{const k=el.id||el.name;if(!k||el.type==='file'||el.type==='password')return;fields[k]=el.type==='checkbox'?el.checked:el.value});
  viewState[view]={scrollY:document.querySelector('.main')?.scrollTop||window.scrollY||0,navScroll:document.querySelector('.nav')?.scrollTop||0,fields};
}
function restoreViewState(v){
  const st=viewState[v];setTimeout(()=>{
    const c=document.getElementById('content');if(!c)return;
    Object.entries(st?.fields||{}).forEach(([k,val])=>{const el=c.querySelector('#'+CSS.escape(k))||c.querySelector('[name="'+String(k).replace(/"/g,'\\"')+'"]');if(el){if(el.type==='checkbox')el.checked=!!val;else el.value=val;try{el.dispatchEvent(new Event('change',{bubbles:true}))}catch(_){}}});
    const main=document.querySelector('.main');if(main)main.scrollTop=st?.scrollY||0;else window.scrollTo(0,st?.scrollY||0);const navEl=document.querySelector('.nav');if(navEl&&st?.navScroll!=null)navEl.scrollTop=st.navScroll;ensureActiveNavVisible();
  },40);
}
async function refreshCurrentView({preserve=true}={}){
  if(currentRefreshPromise)return currentRefreshPromise;
  if(preserve)captureViewState();
  currentRefreshPromise=(async()=>{await loadView();if(preserve)restoreViewState(view);await refreshActionCounts();await refreshNotifCount()})();
  try{await currentRefreshPromise}finally{currentRefreshPromise=null}
}
function scheduleDataSync(delay=120){
  clearTimeout(dataSyncTimer);dataSyncTimer=setTimeout(async()=>{if(!me)return;await Promise.allSettled([refreshActionCounts(),refreshNotifCount()]);if(!formDirty&&document.getElementById('content'))refreshCurrentView({preserve:true}).catch(e=>console.warn('View refresh:',e.message))},Math.max(0,Number(delay)||0));
}
function go(v,opts={}){
  closeMobileSidebar();
  if(v===view&&!opts.force){guardDirty('Refresh this selected tab and reload its latest data?',()=>refreshCurrentView({preserve:true}));return}
  guardDirty('You have unsaved changes. Leave this view and discard them?',()=>{captureViewState();view=v;if(!opts.replace&&!isHistoryNavigation)history.pushState({view,unit:selectedUnitId},'',`#${encodeURIComponent(view)}`);render();restoreViewState(view)});
}

