function correctionFieldHtml(field,record){
  const value=record?.[field.name]??'',required=field.required?'required':'',label=esc(t(field.label))+(field.required?' *':'');
  if(field.type==='select')return `<div class="field"><label>${label}</label><select name="${esc(field.name)}" ${required}>${(field.options||[]).map(option=>`<option value="${esc(option)}" ${String(option)===String(value)?'selected':''}>${esc(t(option))}</option>`).join('')}</select></div>`;
  if(field.type==='textarea')return `<div class="field correction-field-wide"><label>${label}</label><textarea name="${esc(field.name)}" ${required}>${esc(value)}</textarea></div>`;
  const inputValue=field.type==='date'?String(value||'').slice(0,10):value;return `<div class="field"><label>${label}</label><input name="${esc(field.name)}" type="${esc(field.type||'text')}" value="${esc(inputValue)}" ${field.step?`step="${esc(field.step)}"`:''} ${field.type==='number'?'min="0"':''} ${required}></div>`;
}
